window.MON4_DATA = {"2010-07": {"examLabel": "2010-07", "audioSrc": "assets/audio/MD4/N1_7-2010.mp3", "questions": [{"stem": "ご都合のよろしい日をご指示いただけますか。", "choices": ["ええ、そういうことで結構です。", "その日はちょっと都合が悪いんですが。", "じゃ、来週の木曜日にしましょうか。"], "ans": 3}, {"stem": "すみません、営業の山田さんにお会いしたいんですが。", "choices": ["さっそく、お願いします。", "ご案内いただけますか。", "今、呼んでまいります。"], "ans": 3}, {"stem": "今日はお忙しいところおいでいただき、ありがとうございました。", "choices": ["お会いできてよかったです。", "今回はお伺いできなくてすみません。", "どうぞ、またおいでください。"], "ans": 1}, {"stem": "あのう、この計画、このままだとうまくいかないんじゃないでしょうか。", "choices": ["いや、問題ないと思いますけどね。", "本当にうまくいきましたね。", "よし、さっそくいきましょう。"], "ans": 1}, {"stem": "ほら、見て、あの人のプレー、先発チームのメンバーだけのことがあるよね。", "choices": ["うん、さすがちょっと違うよね。", "えっ?メンバーだけじゃないよ。", "そう?結構上手だと思うけど。"], "ans": 1}, {"stem": "この件ですが、山田部長にもお伝えいただけるとありがたいんですが。", "choices": ["よろしく伝えてください。", "お伝えいただけると助かります。", "では、あとで伝えておきます。"], "ans": 3}, {"stem": "この値段、あと少し何とかなりませんか。", "choices": ["そういうわけじゃないんですよ。", "えっ?何か間違いがありましたか?", "うーん、これ以上は難しいですね。"], "ans": 3}, {"stem": "いまさら急いだところで、だめなんじゃない。", "choices": ["えっ、どこにいってきたの。", "いや、とてもいいらしいね。", "だめってことないよ。"], "ans": 3}, {"stem": "田中さんの気配りには、本当に頭が下がりますね。", "choices": ["それは大変なことになりましたね。", "本当に、私も見習いたいと思います。", "早く謝ったほうがいいですよ。"], "ans": 2}, {"stem": "部長、この企画、今度こそ通したいと思います。", "choices": ["期待していますよ。", "ついにやり遂げましたね。", "適切なアドバイス、ありがとう。"], "ans": 1}, {"stem": "あのパソコン、捨てるくらいなら、俺が使いたかったのに。", "choices": ["じゃあ、使い方、教えてあげるね。", "でも、古くて使いにくかったんだよ。", "捨てるなら、あしたにしたら?"], "ans": 2}, {"stem": "では、この件はいったん見合わせるということでよろしいですか。", "choices": ["ええ、どこでお会いしましょうか。", "では、さっそくはじめるということで。", "そうですね、改めて話し合いましょう。"], "ans": 3}, {"stem": "彼を信じて任せたらこの始末だよ。", "choices": ["それはよかったですね。", "それは困りましたね。", "それはありがたいですね。"], "ans": 2}, {"stem": "機械の故障とかいろいろあって、まったく今日はさんざんだったよ。", "choices": ["えっ、大変だったね。", "なかなか順調じゃない?", "毎日こうだったらいいのにね。"], "ans": 1}]}, "2010-12": {"examLabel": "2010-12", "audioSrc": "assets/audio/MD4/N1_12-2010.mp3", "questions": [{"stem": "あの、何か書くもの拝借してもよろしいですか。", "choices": ["じゃあ、拝見しましょう。", "これでよろしければ。", "すぐお返しします。"], "ans": 2}, {"stem": "よし、今度の試験合格してみせるぞ。", "choices": ["やったね、おめでとう。", "じゃあ、受けてみるね。", "受かるといいね。"], "ans": 3}, {"stem": "お忙しいところ恐れ入りますが、一度うちの事務所にお越し願えませんか。", "choices": ["ずいぶんお忙しいんですね。", "来週なら伺えますが。", "もうお越しいただきましたので。"], "ans": 2}, {"stem": "山田貿易の業績最近ずいぶん伸びてるね。", "choices": ["ちょっと短くした方がいいね。", "今の景気では難しいんだね。", "うちも負けてられないね。"], "ans": 3}, {"stem": "さっき返した会議の資料もう一度見せてくれない?気にかかることがあって、", "choices": ["どこか間違ってたでしょうか。", "拝見してもよろしいですか。", "気に入ってもらえましたか。"], "ans": 1}, {"stem": "今度の社員旅行行きたいのは山々なんですけど。", "choices": ["え、行けないんですか。", "今度は山なんですか。", "それは楽しみですね。"], "ans": 1}, {"stem": "悪いけど、今日はゆっくりしてらんないんだ。", "choices": ["どうやって?", "なんかあんの?", "余裕あるんだね。"], "ans": 2}, {"stem": "面接のときこの服じゃまずいかな。", "choices": ["そんなことないと思うけど。", "上手だとは思わないよ。", "そういうわけじゃないんだね。"], "ans": 1}, {"stem": "明日のプレゼン、データ整理に手間取ってて、グラフまで手が回らないよ。", "choices": ["大変だね。手伝おうか。", "もう少し近くに持ってこうか。", "けっこうすんなり終わったね。"], "ans": 1}, {"stem": "あの、これ気持ちばかりのものですが。", "choices": ["お口にあうかどうかわかりませんが。", "ええ、お気持ちはよくわかります。", "かえってお気を使わせてしまいまして。"], "ans": 3}, {"stem": "ねえ、今月の売り上げもトップなんだって。もうかなわないな。", "choices": ["今度こそがんばります。", "や、運がよかっただけです。", "ええ、かなうといいですね。"], "ans": 2}, {"stem": "せっかく来たのに休みだなんて。", "choices": ["来られなくて残念だったね。", "休みだと思ってたのに。", "仕方ないよ。また来よう。"], "ans": 3}, {"stem": "山田先生って経済学ではちょっと名の知れた先生らしいね。", "choices": ["学生のことよく知ってるよね。", "本もたくさん書いてるもんね。", "よくある名前だからね。"], "ans": 2}, {"stem": "出張の件だったら部長に聞くまでもないよ。", "choices": ["じゃあ、聞かないとだめですね。", "でも、念のため聞いてみます。", "やっぱり聞いたほうがいいですか。"], "ans": 2}]}, "2011-07": {"examLabel": "2011-07", "audioSrc": "assets/audio/MD4/N1_7-2011.mp3", "questions": [{"stem": "今日は忙しいところ手伝わせちゃって悪かったね。", "choices": ["えっ、忙しくなるんですか?", "そんなはずはないと思います。", "いいえ、いつでもおっしゃってください。"], "ans": 3}, {"stem": "明日の映画なんだけど、レポートやら、実習やらでそれどころじゃなくなっちゃったんだ。", "choices": ["きっと面白いよね。", "えー、いけないの?残念。", "忙しいのに、よく行ったね。"], "ans": 2}, {"stem": "あのう、こちらの傘、お忘れじゃないですか。", "choices": ["どうぞ、お気をつけください。", "あっ、どうも恐れ入ります。", "お持ちしましょうか。"], "ans": 2}, {"stem": "悪いね、預かった資料、まだ見てないんだよ。ずっと電話が鳴りっぱなしで…", "choices": ["はい、すぐにお電話させますので。", "ただいま席をはずしております。", "では、お時間のあるときにお願いします。"], "ans": 3}, {"stem": "今日の先生の講義、ちんぷんかんぷんだったよ。", "choices": ["丁寧で分かりやすかったね。", "難しくて、私も全然・・・。", "ああいう話って、わくわくするよね。"], "ans": 2}, {"stem": "ああ、あんな負け方するくらいなら、はじめからやるんじゃなかった。", "choices": ["途中からでもやってみたら?", "やってみればよかったね。", "よく頑張ったと思うよ。"], "ans": 3}, {"stem": "あの、先月の家賃なんですけど、まだ振り込まれてないようですが。", "choices": ["すみません、うっかりしてて…。", "では、そうしていただけますか。", "あ、すぐにいただきますので。"], "ans": 1}, {"stem": "もしもし、もうすぐ社に戻るけど、留守中何かなかった?", "choices": ["えっ、どんなご用件でしょうか?", "確かに了解いたしました。", "先ほど、田中様がいらっしゃいました。"], "ans": 3}, {"stem": "あの、もう少し席を詰めていただけるとありがたいんですが…。", "choices": ["あ、気がつきませんで。", "おかげさまで助かりました。", "いや、まだまだですよ。"], "ans": 1}, {"stem": "山本君、まだ来ないね。どういうつもりなんだろう、まったく。", "choices": ["また来るつもりだって。", "時間通りに来たことないよね。", "やっぱり間に合ったんだ。"], "ans": 2}, {"stem": "どうしたの?食事もしないで考え込んじゃって。", "choices": ["いや、それほどでもないと思うよ。", "ちょっと気になってること、あってね。", "どうしてもこの時間、込んじゃうんだよね。"], "ans": 2}, {"stem": "プロジェクトもやっと終わったことだし、ようやく一息付けるね。", "choices": ["一時はどうなることかと思ったよね。", "のんびりできるのももう終わりだね。", "確かにこれからが山場だね。"], "ans": 1}, {"stem": "今度の休み、家族とゆっくり過ごせたらなあと思ってたのにな。", "choices": ["じゃ、そうしてみましょうか。", "ああ、それは楽しみですね。", "えっ、仕事でも入ったんですか?"], "ans": 3}]}, "2011-12": {"examLabel": "2011-12", "audioSrc": "assets/audio/MD4/N1_12-2011.mp3", "questions": [{"stem": "あのう、恐れ入りますが、こちらへの駐車はご遠慮いただいております。", "choices": ["ご遠慮なさらず、どうぞ。", "あっ、気が付かなくて。", "じゃ、せめて車だけでも。"], "ans": 2}, {"stem": "アルバイトさえなければ、昨日のコンサート行ったんだけどなあ。", "choices": ["ああ、アルバイトなくなったんだ。", "コンサート盛り上がった?", "アルバイト、なんとかならなかったの?"], "ans": 3}, {"stem": "この書類、昨日までに先方にお届けするように言ったはずでしょう。", "choices": ["そのように先方に伝えておきます。", "申し訳ありません。至急送ります。", "どうやらそうらしいです。"], "ans": 2}, {"stem": "もし保険の加入をお考えでしたら、ご自宅に案内を送らせて頂きたいのですが。", "choices": ["わざわざ来ていただいては恐縮ですから。", "いえ、特に関心がありませんので。", "え?家まで案内してくださらなくても。"], "ans": 2}, {"stem": "あ〜あ、やってらんないよなあ。今週でプロジェクト打ち切りだなんて。", "choices": ["後すこしで結果出せたのにね。", "評価が高かっただけのことはあるよね。", "やれば出来るってことだね。"], "ans": 1}, {"stem": "この料理、二人分にしちゃ物足りないよね。", "choices": ["うん、食べた気がしないね。", "ひとり分で十分だったよね。", "本当、食べきれないよ。"], "ans": 1}, {"stem": "君がしたことは社会人としてあるまじき行為ですよ。", "choices": ["責任を痛感しております。", "確かに承りました。", "認めていただいてありがとうございます。"], "ans": 1}, {"stem": "部長にしてみれば、今月のうちの部の営業成績は今ひとつなのかなあ。", "choices": ["これも部長のおかげだね。", "納得してない感じだったね。", "確かに満足気だったね。"], "ans": 2}, {"stem": "この分なら、今日残業しなくて済みそうだね。", "choices": ["思ったよりスムーズに進んだもんね。", "残業、早めに済んでよかったね。", "本当に嫌になっちゃうよね。"], "ans": 1}, {"stem": "では、そろそろ新年会もこの辺でお開きにしましょうか。", "choices": ["ああ、この場所がいいですね。", "そうですね。もう遅いですし。", "皆さんおそろいなので、まず乾杯しましょう。"], "ans": 2}, {"stem": "味もさることながら、店の雰囲気作りにも気を遣いました。", "choices": ["じゃ、美味しさは二の次ですね。", "ひたすら味を追求したというわけですね。", "本当に素敵なインテリアですね。"], "ans": 3}, {"stem": "あのう、予算案提出の締切すこし延ばしてもらえないものかと。", "choices": ["お急ぎになるお気持ちは理解できますが。", "では、日にちを繰り上げるということで。", "この日を過ぎると、難しいものですから。"], "ans": 3}, {"stem": "コーヒー、どうぞ。せっかく来ていただいたのに、何もなくて。。", "choices": ["いえいえ、急におじゃましてしまって。", "どうぞ、ゆっくりしてってください。", "では、また日を改めて。"], "ans": 1}]}, "2012-07": {"examLabel": "2012-07", "audioSrc": "assets/audio/MD4/N1_7-2012.mp3", "questions": [{"stem": "すみません、あの方の名前は?", "choices": ["さあ、存じ上げません", "いいえ、お見かけしません", "はい、かしこまりました。"], "ans": 1}, {"stem": "うーん、この企画、やっぱり諦めるしかないよね。", "choices": ["残念だけど、仕方ないよね。", "やっとうまくいきそうだね。", "途中でやめなくてよかったね"], "ans": 1}, {"stem": "リンさん、今日のプレゼ、リンさんの助言がなければうまくいかなかったよ。", "choices": ["すみません、次は頑張ります。", "あ、いえ、お役にたててよかったです。", "え、助言を聞いてくれなかったんですか。"], "ans": 2}, {"stem": "ねえ、これ間違ってるんじゃないかな。", "choices": ["そうね、私も合ってると思う。", "そうかな。私はいいと思うけど。", "いや、間違ってるね。"], "ans": 2}, {"stem": "送別会のお店なんですが、どこかいいところありませんか。", "choices": ["料理がおいしいと評判のお店ですよ。", "皆参加できるといいですね", "うーん、田中さんが詳しいと思いますよ。"], "ans": 3}, {"stem": "マラソン大会に出るからには優勝してみせるよ。", "choices": ["じゃ、出ないんだね。", "出るわけじゃないからね。", "せっかく出るんだもんね。"], "ans": 3}, {"stem": "講演会なんだけど、資料は多めに用意しとくに越したことはないよ。", "choices": ["なるほど、出席者少ないですし。", "じゃ、たくさんコピーしておきます。", "資料は余ったら無駄ですものね。"], "ans": 2}, {"stem": "この書類、今日中に仕上げてもらえると助かるんだけど。", "choices": ["それはいけませんね。", "まったくおっしゃる通りです。", "何とかいけると思います。"], "ans": 3}, {"stem": "どんなに忙しかろうが、報告はおこたるもんじゃないよ。", "choices": ["忙しい時は必要ないんですね。", "今後十分に気を付けます。", "そんなにお忙しいんですか?"], "ans": 2}, {"stem": "もういい加減にしてよ。こんなに待たせて。", "choices": ["次は遅れないようにするから。", "それがちょうどいいね。", "どれぐらい待ったと思う?"], "ans": 1}, {"stem": "先月転職した彼の気持ち、わからなくもないよね。", "choices": ["ほんと、彼の気持ちわからないね。", "やっぱりもう一度考え直してみたら?", "うん、僕も時々ちょっと考えちゃうよ。"], "ans": 3}, {"stem": "あの、お客様、アンケートにご解答いただければと思うのですが。", "choices": ["え?そう思わないんですか。", "時間かかりますか。", "では答えていただけますか。"], "ans": 2}, {"stem": "ご連絡した件ですが、明日までにお返事を頂戴できればと。", "choices": ["確かに頂戴いたしました。", "お返事お待ちしております。", "今日中には必ず。"], "ans": 3}]}, "2012-12": {"examLabel": "2012-12", "audioSrc": "assets/audio/MD4/N1_12-2012.mp3", "questions": [{"stem": "ごめん、待った?駅で足どめくっちゃって。", "choices": ["え?電車動いてなかったの。", "足、大丈夫?痛かったでしょう。", "ちゃんと時間調べて行かなくちゃ。"], "ans": 1}, {"stem": "え?もうこんな時間?今日は接客に時間とられて昼たべそこなったよ。", "choices": ["相当急いで食べたんだね。", "今からでも食堂行ってきたら。", "昼ごはんお客さんといっしょだったの。"], "ans": 2}, {"stem": "もうすぐパーティ始まるから、コップあるだけ出しといて。", "choices": ["じゃ、いくつ出せばいいんですか。", "コップは人数分でね。", "全部たって五個しかないですよ。"], "ans": 3}, {"stem": "先方に共同開発を提案したらすんなり受け入れられたよ。", "choices": ["説得するの、そんなに大変だったの。", "またチャンスはあるから、落ち込まないで。", "向こうもそういう希望があったんじゃない。"], "ans": 3}, {"stem": "テレビで見た新発売の野菜ジュースとてもじゃないけど、飲めたもんじゃなかったよ。", "choices": ["売り切れだったの。", "まあまあだったの。", "そんなにまずいの。"], "ans": 3}, {"stem": "来月の登山ではみんなのお荷物にならないようにしなきゃ。", "choices": ["おいてかれないように頑張ってね。", "登山だもん、あんまりもってけないだろう。", "みんなの荷物まで気にしなくていいよ。"], "ans": 1}, {"stem": "今年の新入社員はものになりそうですよ。", "choices": ["それは期待が持てますね。", "どういうものですか。", "いい人材が集まりませんね。"], "ans": 1}, {"stem": "僕、部長はてっきり出張に行ってるもんだとばかり思ってたよ。", "choices": ["まさか出張なさってるとはね。", "出張キャンセルになったんだって。", "いつ出張から戻られるか知ってる?"], "ans": 2}, {"stem": "留学説明会に出て、自分の準備不足がわかっただけでも収穫あったよ。", "choices": ["出ても無駄だったわけだね。", "納得してないんだね。", "じゃあ、参加した甲斐があったね。"], "ans": 3}, {"stem": "来週の健康診断って絶対受けないといけないってわけじゃないんだって。", "choices": ["それって受けなくてもいいってこと?", "全員受けろうっていうんじゃ仕方ないね。", "絶対に受けないってどうして?"], "ans": 1}, {"stem": "山川食品との交渉なんとか契約にこぎつけたよ。", "choices": ["苦労が報われたね。", "そんなふうにあきらめないでよ。", "つぎこそは契約がとれるといいね。"], "ans": 1}, {"stem": "この辺、コンビニの一軒ぐらいあってもよさそうなものなのにねえ。", "choices": ["たしかに、こんなとこお客さんめったに来ないよね。", "人通りも多いのに、どうしてないのかな。", "一軒だけだからこんなに込んでるんだ。"], "ans": 2}, {"stem": "木村さん、このあいだ大阪に転勤したと思ったら、今度は北海道だって。", "choices": ["そろそろ大阪じゃないかと思ったんだ。", "へえ、大阪に転勤するんじゃなかったんだ。", "大阪、まだ一年にもなってないのにね。"], "ans": 3}, {"stem": "店長、今日は雨が降ってるせいか、朝からお客さんがひっきりなしですね。", "choices": ["やっぱり天気が悪いと、お客さん来ないね。", "雨の日はいつも込むからね。", "それほど空いてるわけじゃないよ。"], "ans": 2}]}, "2013-07": {"examLabel": "2013-07", "audioSrc": "assets/audio/MD4/N1_7-2013.mp3", "questions": [{"stem": "ねえ、会計課の山田君、いつもぼそぼそ話すよね。", "choices": ["もう少しはっきり話してほしいよね。", "もっと静かに話せないのかな。", "本当に聞きやすくていいよね。"], "ans": 1}, {"stem": "昨日の夜中のサッカー中継、うっかりしてて、見逃しちゃったよ。", "choices": ["よく夜中まで見てたね。", "ええ、録画しとかなかったの。", "ボールから目を離しちゃだめだよ。"], "ans": 2}, {"stem": "今日の面接、さんざんだったよ。", "choices": ["しっかり準備しただけのこと、あったね。", "何か失敗でもしたの。", "ありがたい話だね、今日はついてたね。"], "ans": 2}, {"stem": "君の報告書、新入社員でもあるまいし、何なんだ。", "choices": ["お褒めいただきまして。", "すぐに作成し直します。", "努力した甲斐がありました。"], "ans": 2}, {"stem": "さっきからそわそわしちゃって、何かあるの。", "choices": ["えっ、落ち込んでいるように見える。", "ちょっと大事な連絡を待ってるんだ。", "うん、元気いっぱいだよ。"], "ans": 2}, {"stem": "この間、駅前の交差点で幼馴染にばったり出くわしてね。", "choices": ["久々に待ち合わせしたんだ。", "あの交差点、見通し悪いからね。", "それはすごい偶然だね。"], "ans": 3}, {"stem": "うちの子ジョギング始めるって言ってるんだけど、せいぜい三日も続けば上々だろうなあ。", "choices": ["へえ、三日も続いてるのね。", "親としても自慢したくなるよね。", "そんなことないでしょう。"], "ans": 3}, {"stem": "今日、市役所に行ったら、あちこち窓口を盥回しにされて頭にきたよ。", "choices": ["それはどうぞお大事に。", "それって本当いやになるね。", "そんなに用事が多かったんだね。"], "ans": 2}, {"stem": "うちの母、看護師として働くかたわらボランティア活動も熱心にやってるんですよ。", "choices": ["ボランティア活動のついでなんですね。", "仕事一筋のお母さんなんですね。", "見習いたいものですね。"], "ans": 3}, {"stem": "今度のプロジェクトはIT技術に明るい君が打って付けだと思うんだけど、どう?", "choices": ["ご期待に添えるよう頑張ります。", "どなたが適任なんですか。", "私じゃ、技術力が足りないんですか。"], "ans": 1}, {"stem": "企画案、立ててみたけど、果たして部長が首を縦に振るかどうか。", "choices": ["どっちにしても、不採用になったんだ。", "見せてみなきゃ始まらないよ。", "部長が承認してくれて、これでいけるね。"], "ans": 2}, {"stem": "この店の定食、値段のわりには悪くないね。", "choices": ["でしょう、他の店ならもうちょっとするよ。", "確かにあまりにも高すぎるよね。", "そう、そんなにまずいかな。"], "ans": 1}, {"stem": "田中様、本日は足元の悪い中、弊社までお運びいただきまして。", "choices": ["足のお怪我はいかがでしょう。", "そちらに置いていただけますか。", "こちらこそお時間をいただいて。"], "ans": 3}, {"stem": "お客様、そちらはやってるんですよ。よろしければ、お召しになりませんか。", "choices": ["じゃ、試してみます。", "よろしければ差し上げます。", "それなら、ご馳走になります。"], "ans": 1}]}, "2013-12": {"examLabel": "2013-12", "audioSrc": "assets/audio/MD4/N1_12-2013.mp3", "questions": [{"stem": "あの、すみません。こちらの椅子を拝借したいんですが。", "choices": ["じゃ、失礼してこちらの席に。", "えっ、貸してくださるんですか。", "ああ、どうぞお持ちください。"], "ans": 3}, {"stem": "君、ゴルフ、初めてにしては、やるね。", "choices": ["いえ、それほどでも。", "すみません、そんなにご迷惑でしたか。", "初めてでもよろしいんですか。"], "ans": 1}, {"stem": "山下監督の新作映画、来週公開なんだ。ああ、待ちきれないよ。", "choices": ["諦めるにはまだ早いよ。", "来週なんてすぐじゃない。", "あんまり期待してないんだね。"], "ans": 2}, {"stem": "部長、新製品の売上、なんとしても目標を達成してみせます。", "choices": ["おめでとう、頑張りましたね。", "あっ、それならもう見ましたよ。", "いい報告、楽しみにしてます。"], "ans": 3}, {"stem": "ボーリング大会、あんなスコアで恥かくんだったら、僕、出なきゃよかったよ。", "choices": ["やるだけやってみれば。", "本当に出なくてよかったね。", "まあ、そんなこと言わないで"], "ans": 3}, {"stem": "課長に仕事が雑だって言われちゃった。叱られる覚えないんだけどな。", "choices": ["えっ、思い当たること、ないの。", "叱られたのに、忘れちゃったの。", "覚えといたほうがいいんじゃないの。"], "ans": 1}, {"stem": "この料理、森田さんが作っただけあって、手が込んでるよね。", "choices": ["森田さん、料理得意だもんね。", "忙しかったんだから、仕方ないよ。", "本当、皆が手伝ったおかげだよね。"], "ans": 1}, {"stem": "あんな演劇見るくらいなら、うちで寝てたほうがましだったよな。", "choices": ["よかった。誘った甲斐があった。", "そりゃ、うちのほうがゆっくり見られるでしょう。", "まあ、確かに評判のわりにイマイチだったかもね。"], "ans": 3}, {"stem": "新入社員の中島君、若いんだからもう少し体力あってもいいのにね。", "choices": ["若いのになかなか感心だね。", "本当すぐばてちゃうんだから。", "体力あるから助かっちゃうよね。"], "ans": 2}, {"stem": "君のプレゼン、文句のつけようがなかったよ。", "choices": ["そんな、とんでもないです。", "ご指摘ありがとうございます。", "すみません、以後気をつけます。"], "ans": 1}, {"stem": "今日の会議、君が資料を届けてくれなきゃ大変なことになってたよ。", "choices": ["届けられればよかったんだけど。", "困った時はお互いさまだよ。", "それって私のせいってこと。"], "ans": 2}, {"stem": "田中さんって、待ち合わせに30分も遅れたのに、電話すらしてこなかったんだよ。", "choices": ["電話してきたならいいじゃない。", "電話で済ませるなんて失礼だね。", "電話ぐらいしてくれればいいのにね。"], "ans": 3}, {"stem": "なんだかんだあったけど。山田建設との契約、なんとかまとまったよ。", "choices": ["一時はどうなることかと思ったけどね。", "その契約、まとまるといいね。", "努力が無駄んなっちゃったね。"], "ans": 1}, {"stem": "君、問題が起こったら起こったで、すぐ報告してくれないと困るじゃないか。", "choices": ["仮に問題が生じた場合はそういたします。", "お伝えするのが遅れ、申し訳ありません。", "報告したほうがよろしいんじゃないですか。"], "ans": 2}]}, "2014-07": {"examLabel": "2014-07", "audioSrc": "assets/audio/MD4/N1_7-2014.mp3", "questions": [{"stem": "田中くん、聞いたよ。受けた面接全部通るなんて田中くんぐらいだよ。", "choices": ["自分でも情けないです。", "運がよかっただけですよ。", "全員通るなんてすごいですね。"], "ans": 2}, {"stem": "遅くなっちゃってごめん、帰り際に部長に捉まって。", "choices": ["急いでる時に限って、そういうものよね。", "もうちょっと待っててあげたらよかったのに。", "部長ってなかなか捉まらないよね。"], "ans": 1}, {"stem": "うちの社長、いまでこそ成功してるけど、若い頃は挫折の連続だったんだって。", "choices": ["うーん、経営が思わしくないんだ。", "若い頃から成功してたんだね。", "いまの姿からは想像できないよね。"], "ans": 3}, {"stem": "今度の取引先にはちょっと参ってるんだよ。", "choices": ["何かあったんですか。", "うまく行ってよかったですね。", "よく来てくださいました。"], "ans": 1}, {"stem": "週末は天気が崩れるらしいけど、テニス大会は雨天決行としよう。", "choices": ["やっぱり延期するしかないですか。", "いまさら、止めるわけに行かないですからね。", "日程を調整しなくちゃいけませんね。"], "ans": 2}, {"stem": "今度うちに配属された新人だけど、失礼極まりないんだよね。", "choices": ["うーん、礼儀正しいんだ。", "気に障ることでもあったの。", "若いのに感心じゃない。"], "ans": 2}, {"stem": "今日のトラブルについては、部長に報告するまでもないかなぁ。", "choices": ["うーん、お話ししといたほうがいいかと。", "はい。急いで部長にお伝えします。", "じゃ、もう報告ずみなんですね。"], "ans": 1}, {"stem": "今回のこと、なんとお詫びすればいいものか。", "choices": ["お気になさらないでください。", "何がよろしいでしょうか。", "あのう、どうぞご遠慮なく。"], "ans": 1}, {"stem": "衝動買いしたものって、せっかく買っても使わずじまいってことあるよね。", "choices": ["結局、無駄になるのよね。", "よく使い込んでるよね。", "うん、いまが買い時だよね。"], "ans": 1}, {"stem": "今朝は来客が少なかったせいか、ことのほか事務処理が捗ったよ。", "choices": ["時間を浪費しちゃったね。", "それは何よりね。", "うまく行かない時もあるよ。"], "ans": 2}, {"stem": "ねぇ、山田さん、今度の新年会の幹事だけど、木村さんがかって出てくれたんですって?", "choices": ["じゃ、一度は私から頼んでみますよ。", "ええ、自分からやりたいって言ってくれて。", "まぁ、出てもらってもいいじゃないですか。"], "ans": 2}, {"stem": "今回のプロジェクトの成功は君の尽力なくしては得られなかったよ。", "choices": ["今度こそ成功を目指しましょう。", "分かりました。以後留意します。", "チームワークが良かったからですよ。"], "ans": 3}, {"stem": "君の考えた新製品アイディアはともかく、デザインがありきたりなんだよね。", "choices": ["デザインがユニークすぎるんですか。", "では、そのあたりを含めて再検討します。", "褒めて頂けるなんて光栄です。"], "ans": 2}, {"stem": "営業部の中川さんってゴルフの腕前プロ顔負けらしいですよ。", "choices": ["えっ?中川さん負けちゃったんですか。", "あの腕前はプロならではですよね。", "練習のこつを知りたいものですね。"], "ans": 3}]}, "2014-12": {"examLabel": "2014-12", "audioSrc": "assets/audio/MD4/N1_12-2014.mp3", "questions": [{"stem": "ねえ、この店のケーキ甘さ控えめだね。", "choices": ["これなら、甘いの苦手でもいけるね", "それじゃ、ケーキは控えとく", "砂糖が多めなのかもね"], "ans": 1}, {"stem": "今日の決勝戦、見に来たかいあったね。", "choices": ["せっかく都合つけてきたのにね", "本当、来て大正解", "絶対決勝見に行こうね"], "ans": 2}, {"stem": "鈴木さん、市民祭りのイベント鈴木さんにも手伝ってもらえたらと思うんだけど。", "choices": ["大して力になれず、すみませんでした。", "いいえ、そんなふうには思っていませんが", "私でお役に立てることなら、なんでも"], "ans": 3}, {"stem": "りんさん、りんさんはこれから向かう流通センターの担当者と面識あるの?", "choices": ["以前一度だけですが", "これといって問題はありません", "確か二時からの予定です"], "ans": 1}, {"stem": "今日の定例会議、議題山ほどありますね。", "choices": ["言うほど少なくはないですよ。", "重大な議題ってことですか", "あまり長引かないといいんですけど"], "ans": 3}, {"stem": "加藤さん、サービスの改善を検討して、先日の顧客アンケートの結果を踏まえてね。", "choices": ["お客さまの声に答えられるよう、やってみます", "じゃあ、アンケートのほうは後回しで", "調査結果にはこだわらず、がんばります"], "ans": 1}, {"stem": "今度の週末行く旅館、景色もさることながら、食事も格別なんだよ。", "choices": ["どっちも期待膨らんじゃうね", "ひとつもいいとこないじゃない", "なんだ、食事はついてないってこと?"], "ans": 1}, {"stem": "みどり工業との価格交渉、この状況だとそう簡単には・・・。", "choices": ["これからはスムーズに行くかな…", "ちょっと厳しそうだね", "本当、楽な交渉でよかったよね"], "ans": 2}, {"stem": "駅前の老舗のすし屋、行って見たらなんだこんなもんかって感じだったよ。", "choices": ["へーえ、そんなにおいしいんだ", "相変わらず賑わってるんだね", "ふーん、それほどでもないのか"], "ans": 3}, {"stem": "上田さん、頼んでた資料の作成、今日中になんとかなんないかな。", "choices": ["え、今日中に間に合いそうにないんですか", "時間的にどうかと…", "なんとかしていただけるんですね"], "ans": 2}, {"stem": "今日のプレゼン、鋭い質問をよく切り抜けましたね。", "choices": ["あれ、なにが抜けてましたか", "いや、内心焦ってたんですけど", "まあ、一切質問が来なかったんで"], "ans": 2}, {"stem": "リーさん、次の試合は僕、リーさんと対戦だね。お手柔らかに。", "choices": ["もう勝ったつもり", "アドバイスありがとう", "遠慮しないからね"], "ans": 3}, {"stem": "森さん、このたびの弟の就職の件、森さんには感謝してもしきれません。", "choices": ["いや、礼には及びませんよ", "そんなにせめないでください", "私に頼まれても困りますよ"], "ans": 1}, {"stem": "子供に外国語習わせるなら、早く始めるに越したことないよね。", "choices": ["え、習わせなくていいって思ってるの", "え、早く始めても意味ないってこと", "え、そうとは限らないんじゃない"], "ans": 3}]}, "2015-07": {"examLabel": "2015-07", "audioSrc": "assets/audio/MD4/N1_7-2015.mp3", "questions": [{"stem": "先輩、コーヒーでも入れようかと思うんですけど、ちょうどミルク切らしてて。", "choices": ["うん、ミルクはほんのちょっとにしてね。", "あ、ミルク抜きでも構わないよ。", "じゃ、ミルクがいいな。"], "ans": 2}, {"stem": "聞いた?東京支店のイベント、人の集まり今一つだったんだって。", "choices": ["どうやら、日程がまずかったらしいよ。", "え、会場、ひとつにしちゃったんだ。", "よくそんなに来てくれたね。"], "ans": 1}, {"stem": "あ、高橋さん、こんなところでお目にかかれるなんて思いもよりませんでした。", "choices": ["あら、本当、偶然ですね。", "ああ、ここで会えると思ってらしたんですね。", "まあ、わざわざ来てくださるなんて。"], "ans": 1}, {"stem": "あ、雨、天気予報最近当てにならないね。", "choices": ["最近、予報見てないの。", "本当、よく当たるよね。", "しょっちゅう外れてるね。"], "ans": 3}, {"stem": "君が作った会議の予定表見たんだけど、開始時間もう少し早くできないものかな。", "choices": ["じゃあ、一時間あとにずらしましょう。", "あいにく、会議室があいてなかったものですから。", "やはりこれ以上早めるわけにはいかないんですか。"], "ans": 2}, {"stem": "田中君、今度のサークルの旅行、乗り気じゃないんじゃない?", "choices": ["いや、行きたいって思ってるよ。", "えっ、楽しみにしてるのわかる。", "わかった、バスを予約するよ。"], "ans": 1}, {"stem": "佐藤君、さっきの会議の配布資料、助かったよ。急かしちゃって、わるかったね。", "choices": ["では、すぐに取りかかります。", "何とか間に合ってよかったです。", "手伝えなくて、すみませんでした。"], "ans": 2}, {"stem": "鈴木先生、ゴミの減量化について、ご意見をお聞かせ願えますか。", "choices": ["では、ご意見をお聞きいたします。", "お願いしてみてはどうでしょうか。", "それでは、私の考えを。"], "ans": 3}, {"stem": "ねえ、新人の山本君ってビジネスマナーを知らないにもほどがあると思わない?", "choices": ["君がほめるなんて珍しいね。", "彼なりに頑張ってるようだけどね。", "しっかり教育してるだけあるね。"], "ans": 2}, {"stem": "先輩、私が長年取り組んできた研究ですが、とうとう実用化の目処が立ったんです。", "choices": ["すごいね。もう実用化されたんだ。", "気を落とすことないよ。", "努力が実ってよかったね。"], "ans": 3}, {"stem": "新商品のプレゼン、新人の佐藤君に任せたんだけど、荷が重いかな。", "choices": ["かえってチャンスってとらえてるみたいよ。", "荷物運ぶだけなら、私も手伝うわよ。", "断られたんだ。仕方ないね。"], "ans": 1}, {"stem": "部長、さしでがましいようですが、この不況の中、あえて新しい設備にお金をかけるというのは。", "choices": ["そっか。君も賛成してくれるのか。", "どうして反対するのか聞かせてくれる。", "やりたいっていうなら止めはしないけど。"], "ans": 2}, {"stem": "今朝の電車、もう込んでるなんてもんじゃなくて、参ったよ。", "choices": ["へえ、朝からすいてるなんて珍しいわね。", "朝からそれだと、どっと疲れが出そうね。", "毎日今朝みたいだったら、楽なのにね。"], "ans": 2}, {"stem": "山田薬品との共同開発の話、危うく流れるところだったね。", "choices": ["うーん、後一歩のところで流れちゃったね。", "もうどうにもならないのかな。", "一時はどうなることかと思ったけどね。"], "ans": 3}]}, "2015-12": {"examLabel": "2015-12", "audioSrc": "assets/audio/MD4/N1_12-2015.mp3", "questions": [{"stem": "中山さん、明日の試合、出るからには絶対勝てよ。", "choices": ["出るに決まってるでしょう。", "応援してるから頑張ってね。", "そんなにプレッシャーかけないでよ。"], "ans": 3}, {"stem": "あっ、雪だ。これはこの後、お花見どころじゃないね。", "choices": ["雪の中の花見も風情があって、いいと思うけど。", "雪の日はここで花見しちゃいけないんだね。", "雪なのに、花見するっていうの。"], "ans": 1}, {"stem": "部長、こちら、あさっての会議の資料です。事前にご覧いただければと存じます。", "choices": ["いいや、まだ読んでいないんだ。", "会議までに見ておきたいの。", "ああ、目を通しておくよ。"], "ans": 3}, {"stem": "森さん、森さんが調べてくれなきゃ、トラブルの原因分からずじまいだったよ。", "choices": ["分かりました、すぐに調べてみます。", "いいえ、そんな、わかってよかったです。", "すみません、わからずじまいで。"], "ans": 2}, {"stem": "ほら、そこのラーメン屋、すごい行列。列ぶ人の気が知れないよね。", "choices": ["ちょっと、今から列ぶ気。", "いくら人気があっても、列んでまではね。", "確かに、並んだ甲斐がありそうだよね。"], "ans": 2}, {"stem": "企画書、ご持参いただき、ありがとうございます。採用の可否は追ってご連絡ということで。", "choices": ["よろしくご検討のほど、お願いします。", "ここでお待ちしたほうがよろしいですか。", "では、こちらからご連絡するようにします。"], "ans": 1}, {"stem": "今朝の機械の不具合については、解決したし、主任に報告するまでもないか。", "choices": ["一応、伝えといたほうが。", "じゃあ、すぐに主任に連絡します。", "もう報告済みなんですね。"], "ans": 1}, {"stem": "あれっ、なんだ。駅前のカレー屋、今日やってるじゃない。", "choices": ["ええ、やってると思ったのに。", "君が思ってた通りだね。", "休みだと思ってたの。"], "ans": 3}, {"stem": "お客さま、こちらの電球はあいにく在庫を切らしておりまして。", "choices": ["じゃあ、在庫のもので結構です。", "ああ、こちらでは、扱っていないんですね。", "あのう、次に入ってくるのはいつ頃ですか。"], "ans": 3}, {"stem": "先輩が仕事紹介してくれたんだけど、海外勤務の可能性もなくはないみたいで、どうしよう。", "choices": ["海外行くの、いやってこと。", "海外勤務がないから、いいんじゃない。", "そんなに海外で働きたいの。"], "ans": 1}, {"stem": "昨日の山田さんのスピーチ見た?回数熟しているだけのことはあるよね。", "choices": ["本当、何回もやってるはずなのにね。", "堂々としてて、さすがだよね。", "ああ、だからうまく話せなかったのか?"], "ans": 2}, {"stem": "週末、旅行に行ったんですけど、旅先で、さんざんな目に遭いましたよ。", "choices": ["そんなにいろいろいいことあったんですか。", "たとえば、どんな人に会ったんですか。", "何か、困ったことでもあったんですか。"], "ans": 3}, {"stem": "新入生の加藤君って、なんでもずけずけ言うけど、愛嬌があって憎めないね。", "choices": ["なんとも、得な性格だよね。", "そりゃ、加藤君は人を憎んだりしないだろう。", "どうして、そんなにひどいこと言うの。"], "ans": 1}, {"stem": "あの、先日の契約書の件、深くお詫び申し上げます。", "choices": ["どうぞ、お気になさらずに。", "遠慮なくおっしゃってください?", "こちらこそ、大変嬉しく思います。"], "ans": 1}]}, "2016-07": {"examLabel": "2016-07", "audioSrc": "assets/audio/MD4/N1_7-2016.mp3", "questions": [{"stem": "鈴木君、このケーキ食べてみて、これ、砂糖を一切使わずに作ったんだよ。", "choices": ["たくさん入れたんだ。甘すぎない?", "へえ?砂糖とほかになに入れたの?", "えっ?まったく入ってないの?"], "ans": 3}, {"stem": "加藤さん、この前、加藤さんが考えてくれたポスターのデザイン、もう少し何とかならないかな。", "choices": ["どのあたりが気になりますか?", "じゃあ、少し多めに印刷しておきます。", "気に入っていただけて、よかったです。"], "ans": 1}, {"stem": "本田さん、サークルの来年度の部長、本田さんに引き受けてもらえたらって思うんだけど。", "choices": ["あっ、私でよければ、是非やらせてください。", "一度やってみたかったんですが、仕方ないです。", "私のかわりにやってくださるんですか?"], "ans": 1}, {"stem": "お客様、こちら、従業員専用のエレベーターで、ご利用はご遠慮いただいております。", "choices": ["あっ、どうぞ、遠慮なさらずお使いください。", "ではお言葉に甘えて", "気がつかなかったものですから、すみません。"], "ans": 3}, {"stem": "今回の山下監督の新しい映画、なんだかぱっとしなかったよ。", "choices": ["じゃあ、見るのをやめとこうかな。", "ふーん、評判がいいわけだ。", "えっ?映画公開されなかったの?"], "ans": 1}, {"stem": "今日のイベント、来場者数が心配されたけど、前回を上回って、何よりだったね。", "choices": ["あれだけ集まってもまだ足りませんか?", "思ってた以上に好評で、ほっとしました。", "確かに、もう少しきてほしかったですね。"], "ans": 2}, {"stem": "最近、先輩とどうもぎくしゃくしてて...", "choices": ["先輩、体調を崩してたんだ。", "やっと仲直りできたんだね。", "なんか思い当たることないの?"], "ans": 3}, {"stem": "小川さん、今回の取引先との交渉、小川さん一人で進めたいってことだけど、僕はどうかと思うよ。", "choices": ["あのう、一人でやるべきだとお考えですか?", "はい、では早速話しをすすめることにします。", "やはり私一人じゃ無理でしょうか。"], "ans": 3}, {"stem": "営業部の吉田さん、今日もまた遅刻したんだって。部長が怒るのもわからなくもないなあ。", "choices": ["ああ、それで怒らなかったのか", "最近続いてるようだし、無理もないよね", "なんで部長の気持ちわかんないの?"], "ans": 2}, {"stem": "昨日誘ってくれた週末のバーベキュー、行きたいのはやまやまなんだけど...", "choices": ["もちろんきてもらって、かまわないよ。", "えっ?何か予定でもあるの?", "たまに外で食べるのもいいね。"], "ans": 2}, {"stem": "ねえ、田中さん、先月の営業成績がいまいちだったからって、くよくよしたって、はじまらないよ。", "choices": ["うん、落ち込んでても、しょうがないよね", "成績がよかったなんて誰も思ってないよ", "なんだ。まだはじまってなかったんだ"], "ans": 1}, {"stem": "明日提出する経営学のレポート、できたことはできたんだけど、なんだかね。", "choices": ["自信ありそうじゃない", "まだ納得いかないの", "ふーん、うまくまとまったんだね"], "ans": 2}, {"stem": "木村さん、無断で欠勤するなんて非常識にもほどがあるんじゃない?", "choices": ["そういっていただけて、気持ちが落ち着きました。", "今回だけは許していただけるんですね。", "はい、弁解の余地もございません。"], "ans": 3}, {"stem": "佐藤さん、あのデータ処理、佐藤さんが手を貸してくれなければ、昨日徹夜しても終わらなかったよ。", "choices": ["また何かあれば、おっしゃってください。", "徹夜したのに、終わらなかったんですか?", "少しでもお手伝いしたかったんですが..."], "ans": 1}]}, "2016-12": {"examLabel": "2016-12", "audioSrc": "assets/audio/MD4/N1_12-2016.mp3", "questions": [{"stem": "経理部の森田さんって、仕事の傍ら大学院に行ってるんですって。", "choices": ["へえ、大学の経理を担当してるの?", "へえ、両立してるなんてすごいね。", "へえ、会社やめて大学院に行くんだ。"], "ans": 2}, {"stem": "リーさん、リーさんのレポート、結論のとこ、もっとすっきりできないものかな?", "choices": ["これじゃ、すっきりしすぎなんですね。", "あのう、できそうにないでしょうか。", "もう一度見直して、修正します。"], "ans": 3}, {"stem": "新人の伊藤君が、クレーム処理一人でやったって、頼もしいね。", "choices": ["本人によく注意しておきます。", "新人といってもしっかりしてますよ。", "経験が足りないので、仕方ありませんよね。"], "ans": 2}, {"stem": "ねえ、結婚式を間近に控えた今の心境はどう?", "choices": ["いいえ、結婚やめませんよ。", "すばらしかったと思います。", "もうすでに緊張してますよ。"], "ans": 3}, {"stem": "山本くん、プレゼン聞いたよ。やるじゃない?", "choices": ["褒められると、てれるなあ。", "何をやるの?", "やっぱりまずかったか。"], "ans": 1}, {"stem": "初めての会議の司会じゃあるまいし、そんなにかたくならなくても。", "choices": ["初めてだからってこと?", "よかった。会議なくなったのか。", "何回やってもなれないんだよ。"], "ans": 3}, {"stem": "第一ビルの工事の見積書、作成して、前例を踏まえてね。", "choices": ["ああ、前回のも一緒に出すんですね。", "あの、前例はないんでしょうか。", "はい、前のを参考にします。"], "ans": 3}, {"stem": "この間、初めてサーフィンやったんだけど、もうやるもんかって思ったよ。", "choices": ["そんなに楽しかったの?", "一回で懲りちゃった?", "じゃ、またやるつもり?"], "ans": 2}, {"stem": "ねえ、さっき会議で僕が言ったこと、気に障ったんじゃない?", "choices": ["えっ、別にそんなことないよ。", "えっ、うそだったの?そんなあ。", "えっ、よく聞こえてたけど。"], "ans": 1}, {"stem": "武田くん、頼んだ書類の整理、そっちのけで、何やってるの?", "choices": ["もう整理、やる必要ないんですか。", "あっ、すみません、すぐやります。", "えっ、そっちでやるんでしたっけ?"], "ans": 2}, {"stem": "りんさん、プロジェクトがうまく行った暁には昇進だよ。", "choices": ["プロジェクト、うまくいったんですね。", "おかげさまで昇進できました。", "必ず成功させて見せます。"], "ans": 3}, {"stem": "この雨じゃ、イベントに来てくれる方も少ないと思いきや、完全に読みが外れたね。", "choices": ["うれしい誤算でしたね。", "やはり雨の影響は大きかったですね。", "天気予報が外れてよかったですね。"], "ans": 1}, {"stem": "新年会、サッカー部の山田さん来なかったら、盛り上がらなかっただろうね。", "choices": ["山田さんのせいにしちゃ悪いよ。", "山田さんが来てくれてよかったよね。", "山田さんも参加してたんじゃない?"], "ans": 2}, {"stem": "昨日、八歳の孫とアニメ見たんだけど、大人の鑑賞にも十分堪えるもんでしたよ。", "choices": ["そのアニメ、お孫さんには難しすぎたんですね。", "ずっと我慢してアニメを見ていたんですか。", "アニメはもはや子供のものとは言えないらしいですよ。"], "ans": 3}]}, "2017-07": {"examLabel": "2017-07", "audioSrc": "assets/audio/MD4/N1_7-2017.mp3", "questions": [{"stem": "ああ、木村さん、席はずしてた?部長がお探しですよ。", "choices": ["さあ、部長はお見かけしてませんが。", "あっ、すみません。すぐ参ります。", "私も一緒にお探ししましょうか。"], "ans": 2}, {"stem": "森さん、駅前のすし屋、行ってきたよ。森さんが薦めるだけのことはあるね。", "choices": ["うん、僕もすごく気に入ってるんだ。", "そっか。おいしくなかったか。", "僕はなかなかいい店だと思ったんだけどなあ。"], "ans": 1}, {"stem": "おおたさん、受付に置いといたマイク、見当たらないんだけど。", "choices": ["ああ、課長が持ってったよ。", "受付に置いといていいよ。", "ああ、マイク見つかったんだね。"], "ans": 1}, {"stem": "ねえ、今度のゼミの食事会、人多くないし、予約するまでもないよね。", "choices": ["そう。予約入れといたほうがいいよ。", "そうだね。予約する必要ないよね。", "予約してあるなら、心配要らないね。"], "ans": 2}, {"stem": "はらさん、昨年度の販売成績見たよ。日ごろの努力あっての結果だね。", "choices": ["結果が出ずに残念です。", "こつこつ頑張りました。", "努力したんですが、申し訳ありません。"], "ans": 2}, {"stem": "今 倉庫見てきたら、明日の会議に使う椅子埃まみれだったよ。", "choices": ["へえ、埃一つないのか。", "じゃあ、拭かなきゃいけないね。", "椅子そのままでも使えそうで、助かるね。"], "ans": 2}, {"stem": "テストにレポートに来週の発表って、こう重なるとお手上げ。", "choices": ["全部終わってよかったね。", "まあ、何とかなるんじゃない。", "へえ、すっごく前向きだね。"], "ans": 2}, {"stem": "学生の頃、一緒によく行った商店街、なんだか寂れた感じになってたよ。", "choices": ["そう。前はにぎやかだったのにね。", "今も変わらないんだね。", "相変わらず、人が多いんだ。"], "ans": 1}, {"stem": "林さん、企画が通るかどうかは、来週の林さんのプレゼンにかかってるからね。", "choices": ["プレゼンの時間、かかりすぎないようにします。", "来週プレゼンしなくてもいいんでしょうか。", "うまく行くよう、しっかりプレゼンやります。"], "ans": 3}, {"stem": "営業部の山田部長、突然辞めるなんて無責任極まりないですよね。", "choices": ["本当、見習いたいものですね。", "私もあれは理解できません。", "責任感ある行動で、頼もしいですよね。"], "ans": 2}, {"stem": "このセミナーいつも好評だから、資料多めに用意しとくに越したことはないよ。", "choices": ["人数分だけで十分なんですね。", "じゃあ、無駄が出ないよう、少なめにしますね。", "数に余裕を持たせて準備しておきます。"], "ans": 3}, {"stem": "三田さん、新商品の開発、話流れたの、君に非はないよ。", "choices": ["あのう、私に責任があるとのご指摘でしょうか。", "新商品の開発、進めていただけるんですね。", "あっ、お気遣い、ありがとうございます。"], "ans": 3}, {"stem": "リーさん、大学の文化祭で何かスピーチしてほしいんだけど。日本で学ぶ留学生ならではの。", "choices": ["留学生の視点で、ですね。", "留学生向けの話ってことですね。", "私、日本で学ぶ留学生ですけど。"], "ans": 1}]}, "2017-12": {"examLabel": "2017-12", "audioSrc": "assets/audio/MD4/N1_12-2017.mp3", "questions": [{"stem": "私、コンテストに自分の作品応募したんだ。結果が待ち遠しいなあ。", "choices": ["それで、結果はどうだったの。", "あきらめなくてもいいのに。", "何だか自信ありそうだね。"], "ans": 3}, {"stem": "先日は結構な物を頂戴しまして。", "choices": ["あちらは差し上げたんですよ。", "いえ、気に入っていただけたらいいんですが。", "え、何をさったんですか。"], "ans": 2}, {"stem": "うちの息子、大学卒業したんですけど。仕事探そうともしないんですよ。", "choices": ["何かほかにやりたいことがあるんじゃないですか。", "息子さん、仕事が本当にお好きなんですね。", "うーん、就職したくてもできないなんて。"], "ans": 1}, {"stem": "キムさん、この共同研究はキムさんの緻密な分析なくしては成り立たなかったよ。", "choices": ["次は分析ちゃんとやるから。", "え、なくしてしまったの。", "こっちこそいろいろ助けてもらって。"], "ans": 3}, {"stem": "前田さん、こんなところにかばん置いたらつまづいちゃうじゃない。", "choices": ["すみません、邪魔んなんないところに移します。", "いえ、大したかばんじゃありませんから。", "忘れないよう気をつけるので、大丈夫です。"], "ans": 1}, {"stem": "昨日の議事録、課長が今日中に出せって、昨日言っといてほしかったよ。", "choices": ["昨日言われたんだからしかたないよ。", "どうして私が課長に言うの。", "急に言われてもねえ。"], "ans": 3}, {"stem": "バイト先から勤務時間増やすよう頼まれて、今人手足りないから、断るに断れないんだ。", "choices": ["無理ならちゃんと言ったほうがいいよ。", "へえ、断ったのに増やされたの。", "バイト、できるだけたくさんしたいんだね。"], "ans": 1}, {"stem": "今日、大学院の面接試験受けてきた、かなり手応えあったよ。", "choices": ["答えられない質問がかなりあったの。", "うまくいったみたいでよかったじゃない。", "それじゃちょっと心配だよね。"], "ans": 2}, {"stem": "この店の料理、見た目もさることながら、味も抜群ですね。", "choices": ["いいところ一つもありませんか。", "目でも舌でも味わえますね。", "見た目だっていいじゃないですか。"], "ans": 2}, {"stem": "さっき部長に聞いたんだけど、来年度は新入社員の採用、見合わせることになったんだって。", "choices": ["え、何に合わせるの。", "確かに面接で決めるべきだね。", "うーん、不景気の影響かな。"], "ans": 3}, {"stem": "お客様、お食事中すみません。こちらのテーブル、相席をお願いしてもよろしいでしょうか。", "choices": ["あとでもう一人来るんですけど。", "あ、席でお金を払うんですね。", "えっと、どのテーブルに移るんですか。"], "ans": 1}, {"stem": "新年会の幹事、森君が申し出てくれなけりゃ、僕がやらされてたよ。", "choices": ["じゃあ、感謝しないとね。", "大変だけど、幹事頑張ってね。", "ああ、森君に頼まれたの。"], "ans": 1}, {"stem": "加藤さん、加藤さんの企画書見たよ。コスト面で改善の余地あるんじゃないかな。", "choices": ["コスト面についても書いてありますが。", "やってみますが、これ以上は難しいかと。", "ありがとうございます。ではこの方向で行きます。"], "ans": 2}]}, "2018-07": {"examLabel": "2018-07", "audioSrc": "assets/audio/MD4/N1_7-2018.mp3", "questions": [{"stem": "今度のサークルの合宿ぼくも行きたかったなあ。バイトが入ってなかったらなあ。", "choices": ["バイトの予定早く決まればいいね。", "バイト入ってなかったんだ。じゃ、いけるね。", "一緒に行くのを楽しみにしてたのに。"], "ans": 3}, {"stem": "伊藤さん、探してたファイル、そこの棚にあるじゃない。", "choices": ["うん、そこの棚にもないでしょう。", "えっ?本当?あった?。", "早く見つかるといいんだけど。"], "ans": 2}, {"stem": "田中君、さっきの会議での一言、冴えてたね。", "choices": ["ご期待にそえなくて、すみません。", "はあ、一言足りませんでしたか。", "いやあ、今日はたまたまです。"], "ans": 3}, {"stem": "ねえ、知ってる。この前一緒に見た映画で主役だった俳優、あの映画を最後に引退だって。", "choices": ["もう映画に出ないの?結構好きだったんだけど。", "最後はどんな映画に出るんだろうね。", "あの映画で引退を思いとどまったんだね。"], "ans": 1}, {"stem": "新しい会計システムの導入、どうやら一か月ほどずれこむようですよ。", "choices": ["じゃあ、予定通りですね。", "遅れるのは困りますね。", "えっ、早まるんですか?"], "ans": 2}, {"stem": "昨日の打ち上げ、私が余計な事言ったばかりに、雰囲気が悪くなっちゃったんだ。", "choices": ["でも、うっかり言わなくてよかったんじゃないの?。", "そんなに君ばっかり話してたんだ。", "そう。何言ったの?"], "ans": 3}, {"stem": "テニス部の山田君、優勝を逃して、相当落ち込んでるみたいよ。", "choices": ["優勝して目標失ったんだね。", "そっか。残念だったろうね。", "だから、機嫌がいいんだね。"], "ans": 2}, {"stem": "白井さん、商品の発送、あんなにあったのに、こんな短時間でこなしてくれたんだね。", "choices": ["何とか片付きました。", "えっ、もう終わりましたけど。", "どなたか手伝ってくださったんですか。"], "ans": 1}, {"stem": "昨日あなたがやったことは、社会人としてあるまじき行為ですよ。", "choices": ["ありがとうございます。恐れ入ります。", "よくあることなんですね。ほっとしました。", "申し訳ありません。今後気を付けます。"], "ans": 3}, {"stem": "お客様、本日お店の出口でプレゼントをお配りしています。レシートと引き換えにお受け取りください。", "choices": ["レシートを渡せばいいんですね。", "レシートは出口でもらえるんですね。", "レシートは見せなくていいんですね。"], "ans": 1}, {"stem": "今度入った木村さん、あの仕事ぶりじゃ、先が思いやられるなあ。", "choices": ["将来性があるってこと?", "新人なのに、頼もしいね。", "まだ入ったばっかりだから。"], "ans": 3}, {"stem": "あっ、この張り紙見て、このお寺、事前に予約しておかない限り、見学は出来ないって書いてあるよ。", "choices": ["ああ、予約しとかなくてもいいんだ。", "ええ、予約しとけばよかったね。", "せっかく予約しといたのにね。"], "ans": 2}, {"stem": "中田さん、先日のご依頼の件、なかなか厳しいんですが、中田さんからのお話とあってはね。", "choices": ["ご無理をお願いして申し訳ありません。", "やはりだめでしたか。", "私はお受けしにくいんですが。"], "ans": 1}]}, "2018-12": {"examLabel": "2018-12", "audioSrc": "assets/audio/MD4/N1_12-2018.mp3", "questions": [{"stem": "いろいろ検討しましたが、この契約のお話はなかったことにさせてください。", "choices": ["お話しなかったんですか", "今になってそのようなことを言われましても・・・", "では、契約成立ということで"], "ans": 2}, {"stem": "昨日、木村先輩とカラオケ行ったんだけど、もう懲り懲りだよ。", "choices": ["なんか大変なことでもあったの?", "また一緒に行くつもり?", "いいな。何を奢ってもらったの?"], "ans": 1}, {"stem": "会計士の資格、何としても今年取ってみせるよ。", "choices": ["応援してるからね", "よく見えるといいな", "おめでとう、頑張ったね"], "ans": 1}, {"stem": "ランチに良さそうな店、見つけたんだけど、この後、先約ある?", "choices": ["あ、予約はまだなんですけど・・・", "あの、同期の仲間と・・・すみません", "この先には店はないと思います"], "ans": 2}, {"stem": "課長、さっきの件、私、課の皆が何と言おうと反対と言ったら反対です。", "choices": ["皆そう言ってるの?", "ちなみに君は賛成?反対?", "何が何でも反対ってこと?"], "ans": 3}, {"stem": "あの、ファイルの整理はもう少しテキパキやってもらえますか。", "choices": ["間違いに気づかず、すみません", "適当にやったつもりはないんですが、すみません", "要領が掴めなくて、すみません"], "ans": 3}, {"stem": "週末、中学生の姪が遊びに来るんだけど、どこ連れてったらいいか見当もつかないよ。", "choices": ["中学生ならそれがいいんじゃない?", "本人に希望聞いてみたら?", "それじゃ、楽しい週末だったでしょ?"], "ans": 2}, {"stem": "この絵、山田さんが描いただけあって、豪快だよね。", "choices": ["山田さんの作品なのにね", "人柄出てるよね", "あえて豪快に描いてみたんだね"], "ans": 2}, {"stem": "今日は朝からろくなことないんだ", "choices": ["ついてない日ってあるよね", "私だって何もないよ", "へぇー、羨ましいな"], "ans": 1}, {"stem": "この間のトラブル、解決の目処は立ちましたか。", "choices": ["ありがとうございます。助かります", "まだ立て終わってないんです", "まぁ、何とかなりそうです"], "ans": 3}, {"stem": "部長、リーさんの初めての商談、同行しましたが手助けするまでもなかったです。", "choices": ["一人でやれたなんて大したもんだ", "やっぱり商談やらせるのは早すぎたね", "じゃ、リーさんは何も手伝おうとしなかったの?"], "ans": 1}, {"stem": "ねえ、午後4時の時点での今日の売り上げ、集計出てる?", "choices": ["えっと、今日の売り上げ目標ですね", "えっと、4時から今までの集計ですね", "えっと、4時までの売り上げですね"], "ans": 3}, {"stem": "私、この実験結果が出るまで気が気じゃないよ", "choices": ["まぁ、なるようになるよ", "ちょっと安心しすぎなんじゃない?", "僕もそんな気ないよ"], "ans": 1}]}, "2019-07": {"examLabel": "2019-07", "audioSrc": "assets/audio/MD4/N1_7-2019.mp3", "questions": [{"stem": "あーあ、藤田監督の五年ぶりの映画、公開待ち遠しいよね。", "choices": ["早いね。もう見ちゃったの？", "そうだね。早く見たいね。", "ええっ。見たかったのに、残念。"], "ans": 2}, {"stem": "営業部に新しく入った山田君って能力もさることながら、努力家だよね。", "choices": ["うん。優秀だし、本当に頑張ってるよね。", "うーん、力が足りないのは仕方ないよ。", "えっ、努力すれば伸びると思うよ。"], "ans": 1}, {"stem": "先生、あしたの李さんの送別会、最後に一言頂戴したいんですが。", "choices": ["2、3分でいいですか。", "もちろん差し上げますよ。", "李さんから挨拶があるんですね。"], "ans": 2}, {"stem": "先輩、去年の消費者アンケート見当たりません。この部屋の棚という棚を探したんですが。", "choices": ["ええと、この部屋のほかの棚もちゃんと探して。", "そう。念のため、隣の部屋も確認してくれる。", "えっ、棚、見つかんなかったの？"], "ans": 2}, {"stem": "昨日のテニスの決勝、見ていて、手に汗握る試合だったね。", "choices": ["ああ、安心して見てられたよね。", "えっ、つまらない試合だった？", "本当、ハラハラしたね。"], "ans": 3}, {"stem": "黒田さん、この資料、印刷する前に見せてって私言ったじゃないですか。", "choices": ["申し訳ありません。うっかりしてました。", "お見せしなくてもいいんですか。", "私はそんなこと言っていませんが。"], "ans": 1}, {"stem": "この前買った新しいソファー、なんか部屋にしっくりこないんだ。", "choices": ["うちに帰る楽しみだね。", "雰囲気に合わないってこと。", "じゃ、どうやって部屋に入れるの？"], "ans": 2}, {"stem": "新しいサービスの提案書、一緒に案を練ってもらったけど、会議でぼつになったよ。", "choices": ["採用されたんですね。", "何が問題だったんでしょうか。", "結果はいつ出るんですか？"], "ans": 2}, {"stem": "貸してくれたDVD見たよ。最後の結末には意表を突かれたよ。", "choices": ["えっ、最後、驚かなかったの。", "予想外の展開だったでしょう。", "疲れるほど長い話じゃないと思うけど。"], "ans": 2}, {"stem": "出張で泊まったホテル、ネットの口コミを見る限りでは、評判よかったんだけどね。", "choices": ["えー、なんで口コミ見て決めなかったの？", "へえ、口コミ通りだったんだね。", "そう。ネットの口コミってあてにならないよね。"], "ans": 3}, {"stem": "同窓会で幹事をやらされる羽目になっちゃったよ。", "choices": ["大変だろうけど、いい経験になると思うよ。", "えっ、引き受けたらよかったのに。", "あ、ほかにやってくれる人見つかったんだ。"], "ans": 1}, {"stem": "今回の取引先との交渉、森田課長が助けてくれなければ成立しなかったよね。", "choices": ["課長って頼りになるよね。", "課長が助けてくれないとはね。", "助けてもらったのに、うまくいかなかったね。"], "ans": 1}, {"stem": "中野さん、一人で旅行に行くって聞いたけど、行き慣れたところでも用心するにしたことはないよ。", "choices": ["確かに、よく行く場所なら安心ですね。", "うーん、気を付けたほうがいいですよ。", "ありがとうございます。油断しないようにします。"], "ans": 3}]}, "2019-12": {"examLabel": "2019-12", "audioSrc": "assets/audio/MD4/N1_12-2019.mp3", "questions": [{"stem": "コーチ、この雨じゃ、試合中止もやむを得ないでしょうね。", "choices": ["じゃ、やむまでやりましょう。", "これじゃ、無理ですね。", "ああ、雨、やみそうですか。"], "ans": 2}, {"stem": "さっき作ってくれたこの見積書、合計金額が抜けてるよ。", "choices": ["すみません、計算が間違ってましたか。", "すみません、合計書がないほうがよかったんですね。", "すみません、書き入れて出し直します。"], "ans": 3}, {"stem": "このお菓子、材料にこだわってるからっていい値段したけど、それだけのことはあるよね。", "choices": ["期待を裏切らないね。", "材料にこだわってるのにね。", "いいのは値段だけってことだね。"], "ans": 1}, {"stem": "あ、山下さん、こんなところでお会いするなんて。", "choices": ["あ、待っててくださったんですか。", "本当、思いもしませんでした。", "先もここでお会いしましたっけ。"], "ans": 2}, {"stem": "木村さん、今日のプレゼンもまったく危なげない出来でしたね。", "choices": ["そんなことないです。緊張しちゃって。", "毎回ひやひやさせてすみません。", "危なかったですか。気がつきませんでした。"], "ans": 1}, {"stem": "田中さん、部長今海外出張から戻ったと思ったら出てったけど、なに?", "choices": ["じゃ、出張から戻ったら教えて。", "トラブルがあって、その対応みたい。", "え、これからまた海外に行くの。"], "ans": 2}, {"stem": "この海の絵、子供ならではの感性で描かれてて面白いですね。", "choices": ["本当、まるで子供が描いたみたいですね。", "子どもの発想って本当に素晴らしいですね。", "確かに子供ならもっと自由に描くでしょうね。"], "ans": 2}, {"stem": "山田さん、君、新しい企画の担当、買って出たんだって。", "choices": ["それが結局かえなかったので。", "ぜひやってみたいと思いまして。", "え、今度そんな企画が出たんですか。"], "ans": 2}, {"stem": "ゼミの加藤さんと鈴木さん、最近ぎくしゃくしてない?", "choices": ["何かもめたのかな。", "えっ、二人で一緒に？", "確かに忙しそうにしてるね。"], "ans": 1}, {"stem": "昨日出してくれた新商品の企画書、よかったよ。まあ、商品名はありきたりと言えなくもないけど。", "choices": ["あの、よかったの。商品名だけでしょうか。", "いえ、似たような商品名もたくさんあるはずです。", "商品名もう一度考え直します。"], "ans": 3}, {"stem": "初めての登山で雪山に登るなんて、田中君の挑戦、むちゃにもほどがあるよね。", "choices": ["いったい何考えてるんだろうね。", "そんなむちゃなこと言わないでよ。", "関心するほどのことじゃないよ。"], "ans": 1}, {"stem": "森さん、森さんたちが作ったソフトウエア、発売前なのに、問い合わせひっきりなしだって。", "choices": ["少しは人気が出てもいいのになあ。", "いや、問い合わせはゼロじゃないよ。", "なんだかものすごい反響なんだよ。"], "ans": 3}, {"stem": "今日って、何か急ぎの案件抱えてたりする?", "choices": ["まだ何も考えてません。", "特にないですが、何でしょうか。", "今日は荷物は持ってきてないです。"], "ans": 2}]}, "2020-12": {"examLabel": "2020-12", "audioSrc": "assets/audio/MD4/N1_12-2020.mp3", "questions": [{"stem": "木村さん。この資料、会議までに目を通しといてね。", "choices": ["あ、読んでおきます。", "え？私が直すんですか？", "確認よろしくお願いします。"], "ans": 1}, {"stem": "駅前にできたレストラン行ってみたけど二度と行くもんかって思った。", "choices": ["もう2度も行ったの？", "へぇー、そんなに気に入ったの？", "なんで？サービスがひどかったの？"], "ans": 3}, {"stem": "会議中に居眠りして、もう君ぐらいだよ。", "choices": ["あ、他にもいましたか。", "何を考えているんでしょうかね。", "すみません。以後、気をつけます。"], "ans": 3}, {"stem": "お客様、ずいぶん髪伸びましたね。今日はどのようになさいますか?", "choices": ["プレゼント用なので華やかにしてください。", "一口大の大きさに切っていただけますか？", "後ろを少し短めでお願いします。"], "ans": 3}, {"stem": "今日が締め切りの心理学のレポート、まとめるの難しかったよ。出す事は出したんだけどね。", "choices": ["レポート自信あるんだね。", "とりあえず出せたんだからよかったんじゃない？", "早く出しに行った方がいいよ。"], "ans": 2}, {"stem": "鈴木くん、このケーキ食べてみて。これ砂糖を一切使わずに作ったんだよ。", "choices": ["たくさん入れたの？甘すぎない？", "へぇー、砂糖と他に何入れたの？", "全く入ってないの？"], "ans": 3}, {"stem": "先生。僕、絶対第一志望の大学に合格してみせます。", "choices": ["受かると思いましたよ。おめでとう。", "頑張ってください。応援してますよ。", "気を落とさないでください。"], "ans": 2}, {"stem": "野原さん。今月の売り上げ目標の達成は野原さんの活躍によるものだと言っても過言じゃないよ。", "choices": ["お褒めいただき恐縮です。", "申し訳ありません。私の責任です。", "残念です。みんなで頑張ったんですが…"], "ans": 1}, {"stem": "ねぇ、妹の誕生日プレゼント、市販のクッキーじゃ味気ないかな?", "choices": ["じゃ、可愛いカードでも添えたら？", "ちょっと甘みが足りないかもね。", "妹さんがクッキー焼いてくれたの？"], "ans": 1}, {"stem": "あのー、次回の御社との打ち合わせですが、時間の変更ができないものかと思いまして...", "choices": ["できないんですか。困りましたね。", "申し訳ありませんが、お願いできますでしょうか。", "はぁ、そうしますといつをご希望ですか？"], "ans": 3}, {"stem": "新人の中田さんなんだけど、私が仕事を教えてる時、メモを取ろうともしないんだよ。", "choices": ["へぇー、熱心にメモを取ってるなんて感心だね。", "そっか。メモぐらい取ってほしいよね。", "メモを取ってるけど、話聞いてないんだね。"], "ans": 2}, {"stem": "いやー僕、全国大会で優勝できて、これ以上の達成感はないよ", "choices": ["本当によかったね。努力してたもんね。", "何かやり残したことがあるの？", "最後まで諦めないで。まだわからないよ。"], "ans": 1}, {"stem": "ねぇ、日曜のキャンプ、雨が降っても大雨にならない限り予定通りでいいよね?", "choices": ["うん。大雨だったらやめるしかないけどね。", "あー、大雨だからキャンプは行かないんだね。", "え？大雨でも予定通りやるつもり？"], "ans": 1}]}, "2021-07": {"examLabel": "2021-07", "audioSrc": "assets/audio/MD4/N1_7-2021.mp3", "questions": [{"stem": "ううん、むしゃくしゃする", "choices": ["え？それは残念ね。", "ふーん、そんなことはないよ。", "何？どうしたの？"], "ans": 3}, {"stem": "恐れ入ります。劇場内でのご飲食はお控えいただけますか。", "choices": ["あ、はい。すみません。", "ええ、どうぞ。ご遠慮なく。", "劇場の中ならいいんですね。"], "ans": 1}, {"stem": "また休日出勤なんて冗談じゃないよね。", "choices": ["もう冗談もほどほどにね。", "本当？休みでよかった。", "あーぁ、約束キャンセルしなくちゃ。"], "ans": 3}, {"stem": "田中部長、今度のプロジェクトのことで田中部長にご意見をいただけたらと思うんですが。", "choices": ["うん、構わないよ。何？", "まだ何も言ってないよ。", "是非聞かせてほしいな。"], "ans": 1}, {"stem": "新しく入った加藤さんって、テニス、昔やってただけあるよね。", "choices": ["期待してたほどじゃないってこと？", "テニス始めたばかりなんだね。", "経験があるとやっぱり上手だね。"], "ans": 3}, {"stem": "どうでしょう、お客様。そちらお気に召しましたか。", "choices": ["すぐ気がついたわ。", "とても気に入ったわ。", "ちょっと気に障ったわ。"], "ans": 2}, {"stem": "この辺、コンビニの1軒ぐらいあっても良さそうなものなのにね。", "choices": ["確かにこんなとこ、お客さんめったに来ないよね。", "人通りも多いのにどうしてないのかな。", "一軒だけだからこんなに込んでるんだ。"], "ans": 2}, {"stem": "これ、新しい企画なんだけど、会議通るかな", "choices": ["じゃ、それは問題ですね。", "いや、いい問題ですよ。", "うん、問題ないですよ。"], "ans": 3}, {"stem": "最近うちの店によく来るお客さん、何かにつけて文句言ってくるんだよ。", "choices": ["その人、同じことを何度も言うんだね。", "え？例えばどんなことを言うの？", "へえ？どんな物を付けて来るの？"], "ans": 2}, {"stem": "新しく始まったドラマ見た?何だか設定がありきたりだと思わない?", "choices": ["確かに、今までにない面白い設定だよね。", "そうだね。目新しい感じはしないよね。", "もうちょっと普通の方がよかったよね。"], "ans": 2}, {"stem": "この間頼まれたマニュアルの翻訳、来週ならできなくもないよ。", "choices": ["来週はどうしても無理？", "じゃ、お願いできる？", "それで最近忙しそうなんだね。"], "ans": 2}, {"stem": "山田さん。この仕事、山田さんが手伝ってくれなければ、今日中に終わらなかったよ。", "choices": ["お役に立てて何よりです。", "お手伝いできればよかったんですが…", "終わらなくて残念でしたね。"], "ans": 1}, {"stem": "この料理、2人分にしちゃ物足りないよね。", "choices": ["うん、食べた気がしないね。", "1人分で十分だったよね。", "本当、食べきれないよ。"], "ans": 1}]}, "2022-07": {"examLabel": "2022-07", "audioSrc": "assets/audio/MD4/N1_7-2022.mp3", "questions": [{"stem": "山下さん、東町の工事、スケジュールがかなりずれ込んでるって?", "choices": ["おかげさまで順調に進んでいます。", "おっしゃる通り、完成まであと一歩です。", "天候が悪くて遅れが出ています。"], "ans": 3}, {"stem": "昨日のドラマ、思いもよらない展開だったね。", "choices": ["最初からどうなるか分かってたの？", "予想通りだったね。", "本当びっくりしたよね。"], "ans": 3}, {"stem": "中川さん、来年度の予算の件、部長と話し合ったところで変更は難しいんじゃないかなあ。", "choices": ["ええ、話しても仕方ないかもしれませんね。", "あっ、やっと話を聞いてもらえたんですね。", "話し合ったのに難しそうなんですか？"], "ans": 1}, {"stem": "本日の健康診断の結果をお伝えしますので、来週の火曜日以降にお越し願えますか?", "choices": ["火曜日に電話すればいいんですね。", "では火曜日に参ります。", "あぁ、火曜日に送っていただけるんですか？"], "ans": 2}, {"stem": "駅前の病院、夜中だろうと休日だろうと診てくれるらしいよ。", "choices": ["休日だけでもやってほしいね。", "それは助かるね。", "夜中と休日だけ診るって珍しいね。"], "ans": 2}, {"stem": "田中君、この大会、田中君の努力あっての優勝だね。", "choices": ["頑張ったんだけどね。", "もっと努力したほうがよかったってこと？", "みんなの応援のおかげだよ。"], "ans": 3}, {"stem": "雄太、今日の宿題ほったらかしにしてない?", "choices": ["もうやったってどうしてわかるの？", "何にもやらなくていいんだね？", "もうちょっと後でやるよ。"], "ans": 3}, {"stem": "課長、今日のプレゼンですが、取引相手にも事前に資料を渡しておくべきでした。", "choices": ["そうですね、今後は用意するようにしてください。", "資料渡しておいて正解でしたね。", "相手も事前に見られて良かったんじゃないですか？"], "ans": 1}, {"stem": "授業の課題で最近切羽詰まってるんだ。", "choices": ["無理しないでね。", "諦めちゃったんだ。", "楽そうでいいね。"], "ans": 1}, {"stem": "あ、佐藤さん、お借りしていたビデオカメラ、明日にでもお返しにあがります。", "choices": ["ああ、いつでも構いませんよ。", "わざわざ送っていただかなくても大丈夫ですよ。", "こちらから伺うのはちょっと難しいんですが。"], "ans": 1}, {"stem": "先輩、内田電気との打ち合わせ、先輩がいなければどうなっていたことか。", "choices": ["結局間に合わなかったね。", "ごめん、私の発言で混乱させちゃったね。", "役に立ててよかったよ。"], "ans": 3}, {"stem": "新商品の販売イベントの成功は晴れるか否かにかかっていますね。", "choices": ["天気によって客の集まりが違いますからね。", "天気に関係なく成功するってことですか。", "天気と客の数には関連がないですもんね。"], "ans": 1}, {"stem": "内田さん、内田さんが開発したこのメガネ、デザインもさることながら、軽さが見事ですね。", "choices": ["たしかにデザインは改良の必要がありますね。", "デザインも軽さも売りなんです。", "それなら始めから作り直します。"], "ans": 2}]}, "2021-12": {"examLabel": "2021-12", "audioSrc": "assets/audio/MD4/N1_12-2021.mp3", "questions": [{"stem": "港劇団の公演、今日なんだ。本当に待ち遠しかったよ。", "choices": ["期待してなかったんだね。", "へえ、そんなに好きなんだ。", "もう少し待てば良かったのに。"], "ans": 2}, {"stem": "君の報告書、新入社員でもあるまいし、何なんだ。", "choices": ["お褒め頂きまして。", "すぐに作成し直します。", "努力したかいがありました。"], "ans": 2}, {"stem": "聞いた?水泳の伊藤選手、明日の世界大会を最後に引退だって。", "choices": ["え、明日で終わり？ずっと応援してたのに。", "もう引退しちゃったの？残念。", "やっぱり続けることに決めたんだね。"], "ans": 1}, {"stem": "営業部の田中さんと加藤さんが結婚するなんて、思いもしなかったよ。", "choices": ["予想通りだったってこと？", "へえ、結婚はやめたんだね。", "私もまさかって思ったよ。"], "ans": 3}, {"stem": "この作品、君ならではのデザインになってるね。", "choices": ["それは困りましたね。", "それは嬉しいですね。", "それは羨ましいですね。"], "ans": 2}, {"stem": "今回のあなたの行動はチームのキャプテンとしてあるまじき行いですよ。", "choices": ["遠慮させていただきます。", "お役に立てましたか。", "すみません、反省しています。"], "ans": 3}, {"stem": "ボーリング大会あんなスコアで恥かくんだったら、僕、出なきゃよかったよ。", "choices": ["やるだけやってみれば？", "本当に出なくてよかったね。", "まあ、そんなこと言わないで。"], "ans": 3}, {"stem": "お父さん、買い物に行ったきりなのよ", "choices": ["え、まだ出かけてないの？", "え、まだ帰ってきてないの？", "え、もう戻ってきたの？"], "ans": 2}, {"stem": "村田さん、報告書の提出、いつまでかかってるの?遅いにもほどがありますよ。", "choices": ["申し訳ありません。できるだけ早くだします。", "遅くならずに済みそうです。", "ありがとうございます。助かります。"], "ans": 1}, {"stem": "あのう、今もらったレシートを見たんですが、サラダ2つも頼んだ覚えないんですけど。", "choices": ["あ、二つではありませんでしたか。確認いたします。", "追加で注文なさったということでしょうか。", "サラダの数、足りなかったでしょうか。"], "ans": 1}, {"stem": "森さん、森さんが担当したイベント、無事に終わって何よりだったね。", "choices": ["何事もなくてホッとしたよ。", "え、他になにをすればよかったの？", "無事に終わるといいんだけど？？"], "ans": 1}, {"stem": "うーん、これが原因じゃないんじゃないですか。", "choices": ["ええ、私もこれが原因だと思います。", "ええ、原因はないと思います。", "ええ、他の原因が考えられると思います。"], "ans": 3}, {"stem": "ごめん、待った?駅で足止め食っちゃって。", "choices": ["え？電車動いてなかったの？", "足、大丈夫？痛かったでしょう。", "ちゃんと時間調べて行かなくちゃ。"], "ans": 1}]}, "2026-07": {"examLabel": "2026-07", "audioSrc": "assets/audio/MD4/N1_7-2026.mp3", "questions": [{"stem": "桜舎の人たちと一緒に仕事するのはコリゴリですよね。", "choices": ["ご一緒できてよかったですね", "ほんと苦労しましたね", "またぜひ仕事したいですよね"], "ans": 2}, {"stem": "木村さん、お客さんに頼まれたからって安くするにも程があるんじゃない?", "choices": ["安くするほどいいんだね", "もっと安くした方がよかった?", "次からは気をつけるよ"], "ans": 3}, {"stem": "山下さん、来月の自治会の集まりですが、参加するにせよしないにせよ、出欠をお知らせいただけますか?", "choices": ["参加する人は連絡する必要ないってことですね", "いずれにしても予定が分かったらお伝えしますね", "不参加の場合のみ、お知らせすればいいですよね"], "ans": 2}, {"stem": "岡本さんが何だか不機嫌なんだけど、理由聞くに聞けなくて。", "choices": ["どうして不機嫌なのか聞きたくないんだ", "理由、何で言ってた?", "聞いたら余計に機嫌悪くなりそうだもんね"], "ans": 3}, {"stem": "ねえ、物価が上がった分、アルバイト代にも反映して欲しくない?", "choices": ["ほんと、物価に合わせて上がらないかな", "ちょうど物価と釣り合ってるね", "え?物価とは関係なくあげてほしいの?"], "ans": 1}, {"stem": "最新のスマホ買ってって親に頼んだら、軽くあしらわれたわよ。", "choices": ["高いし、なかなか買ってもらえないよね", "簡単にお金出してくれたんだ", "買ってもらえそうでラッキーじゃない?"], "ans": 1}, {"stem": "織田さんは学生会の会長だけあるよね。", "choices": ["彼ならきっと会長になれるよね", "いかにもリーダーって感じだよね", "会長にふさわしくないの?"], "ans": 2}, {"stem": "アオバ機械への納品の日程、あちらの都合で変更を余儀なくされました。", "choices": ["変更せずに済んで助かりましたね", "うちの都合を聞いてもらえたんですね", "スケジュールを調整しないといけないですね"], "ans": 3}, {"stem": "去年発売したうちのチーズ、人気俳優のコメントを機に、売り上げが急に伸びましたね。", "choices": ["確かに、あれがきっかけで売れましたね", "発売直後からよく売れましたもんね", "売れたのはコメントと関係ないってことですか?"], "ans": 1}, {"stem": "週末の学園祭、台風の影響で中止の可能性も否定できないって。", "choices": ["え?中止になっちゃったの?", "よかった、中止の心配は全くないんだ", "そう、中止にならないといいけど"], "ans": 3}, {"stem": "南電気からの機械の購入ですが、いくら条件がよかろうと、相手への即答は避けてくださいね。", "choices": ["いい条件を出されても慎重に進めます", "条件によっては即答してもいいですよね", "では、すぐに契約に移ります"], "ans": 1}]}, "2022-12": {"examLabel": "2022-12", "audioSrc": "assets/audio/MD4/N1_12-2022.mp3", "questions": [{"stem": "お客様、そちらは新作のジャケットです。よかったらお召しになってみてください。", "choices": ["あ、遠慮なくいただきます。", "後でお召しになります。", "じゃあこれ、試着します。"], "ans": 3}, {"stem": "うちの新人たち、みんな必ず契約取ってみせるって、営業に向かったよ。", "choices": ["やる気があっていいね。", "え？何を見せてもらったの？", "契約取れてよかったね。"], "ans": 1}, {"stem": "今の映画のラストシーン、映像と繊細な音楽が相まって印象的だったね。", "choices": ["ほんと、上手く引き立て合ってたね。", "音楽が邪魔だったってこと？", "確かにどっちもいまいちだったね。"], "ans": 1}, {"stem": "お客様、本日お席にご案内できるまで、お時間頂戴しそうなんですが。", "choices": ["あ、ちょうど空いてましたね。", "じゃあ、急ぎます。", "どのくらい待ちますか？"], "ans": 3}, {"stem": "総務の佐藤さんの細やかな対応にはいつも頭がさがるよ。", "choices": ["そんなに不満なんだ。", "ほんと、尊敬するよね。", "注意してあげたら？"], "ans": 2}, {"stem": "今回のプロジェクトは御社のご協力無くしては成功しませんでしたよ。", "choices": ["お力になれて何よりです。", "ご協力できればよかったんですが。", "私どもの力不足でした。"], "ans": 1}, {"stem": "村田さん。来週緑山に初めて登るでしょ?初級者向けの山だけど用心に越したことはないからね。", "choices": ["確かに用心し過ぎですね。", "簡単そうで安心しました。", "注意して臨みます。"], "ans": 3}, {"stem": "最近涼しいのにアイスこんなに仕入れて売れる見込み無いんじゃない?", "choices": ["もう少し仕入れておきましょうか？", "よかった。売れ始めたんですね。", "いやぁ、需要あると思いますよ。"], "ans": 3}, {"stem": "サークルのことで相談があるって言ってたよね?今日の夕方だったら時間取れなくもないよ。", "choices": ["今日は無理なんだね。", "忙しいのに悪いね。", "夕方までだね。分かった！"], "ans": 2}, {"stem": "さっき見た映画、", "choices": ["アクションシーンだから仕方ないよ。", "ちょっと物足りなかったね。", "そんなに気にいったんだ？"], "ans": 2}, {"stem": "先生に頼まれた文献集め、思いの外、はかどらなかったね。", "choices": ["長時間探した割にはね。", "順調にできてよかったね。", "一つも見つからなかったの？"], "ans": 1}]}, "2023-07": {"examLabel": "2023-07", "audioSrc": "assets/audio/MD4/N1_7-2023.mp3", "questions": [{"stem": "あの~山田さん、来週の花見行くにせよ行かないにせよ連絡してくださいね。", "choices": ["行く場合にだけ連絡するんですね。", "決まったらお知らせしますね。", "参加しない方がいいってことですか？"], "ans": 2}, {"stem": "ホクメイ君、料理の腕が上がったんじゃない?", "choices": ["分かる？自分でもそう思う。", "全然上達してない？", "どうしたら上手になると思う？"], "ans": 1}, {"stem": "佐藤さん、新商品のポスター案見たんですが、うちの会社の", "choices": ["イメージに合ってるってことで安心しました。", "どのあたりを直せばいいでしょうか？", "うちの会社らしいポスターですよね。"], "ans": 2}, {"stem": "内田さん、青山さんが作ったサークルのチラシ、イラストが趣味ってだけあるよね。", "choices": ["そう？他の人にお願いしてみる？", "趣味程度じゃだめか。", "うん、さすがだね！"], "ans": 3}, {"stem": "ジョジョさん、来週の出張、私の代理で行ってもらうわけにいかないかな?", "choices": ["私、行かせてもらえないんですか？", "では、気をつけて行ってきてください。", "来週ですね。可能です。"], "ans": 3}, {"stem": "ここの料理は本当に美味しいね。どれも", "choices": ["本田シェフじゃなきゃ、思いつかないね。", "本田シェフには考えられそうにないね。", "本田シェフでも出せないアイデアだね。"], "ans": 1}, {"stem": "昨日の天気予報で大雪って言ってくれていたなら今日のイベント中止したんだけど。", "choices": ["ここまで降るって言ってませんでしたよね。", "天気予報が当たって大雪でしたね。", "言ってた通り、降りませんでしたね。"], "ans": 1}, {"stem": "北溟大学との共同研究の話、進展がないようだね。", "choices": ["確かにスムーズに話が進んでいます。", "全て終わってよかったです。", "全く意見が合わなくて。"], "ans": 3}, {"stem": "部長がOKを出さない限り海外での商品販売は許可されないんだって。", "choices": ["部長OKしてくれたんだ。", "部長次第だってこと？", "部長の許可は要らないんだね。"], "ans": 2}, {"stem": "村田さん、手袋せずに作業するなんて危険極まりないよ。", "choices": ["しなくても大丈夫ってことですか？", "すぐにします。不注意でした。", "それほど危険じゃないんですね。"], "ans": 2}, {"stem": "展示会で製品が並ぶとわが社のバイクが他社のバイクより劣っているのは否めないね。", "choices": ["品質の差が表れてしまいましたね。", "改良を重ねた甲斐がありましたね。", "ええ、どこの製品にも負けてないですね。"], "ans": 1}]}, "2023-12": {"examLabel": "2023-12", "audioSrc": "assets/audio/MD4/N1_12-2023.mp3", "questions": [{"stem": "先月バイトで入った小野さん、うちのチームに馴染んでますね。", "choices": ["まだ入ったばかりですから仕方ないですよ", "いつの間にか溶け込んでますね", "チームの雰囲気が合わないんでしょうか"], "ans": 2}, {"stem": "昨日見たミュージカル、最後のダンスシーンが見られただけでも見に行った甲斐があったね。", "choices": ["最後のシーンだけがイマイチだったんだね", "ダンスシーンが良ければもっと良かったってことか", "あのシーン最高に盛り上がったよね"], "ans": 3}, {"stem": "うちの会社、アオバ電機と合併するか否かで役員が揉めてるみたいだね。", "choices": ["うーん、決まるまでは落ち着かないね", "ああ、合併はしないんだね", "え、合併決まったんだ"], "ans": 1}, {"stem": "知ってた?このお寺、釘は一切使われていないんだって。", "choices": ["え、釘のほかに何を使ってるの?", "ああ、たくさん使ったんだね", "へぇー、一本も使わずに?"], "ans": 3}, {"stem": "駅前にできたラーメン屋に行ったけど、1時間並んでまで食べるほどじゃなかったよ。", "choices": ["並んだ甲斐があったね", "結局食べられなかったんだ", "期待外れだったんだね"], "ans": 3}, {"stem": "昨日カラオケで森さんが歌うのを聞いたんですが、プロ顔負けでしたよ。", "choices": ["へぇー、そんなに上手なんですか?", "プロと比べられないのは当然ですよ", "え?森さんってプロを目指してたんですか?"], "ans": 1}, {"stem": "ミドリ電機に新事業の提案書を持ってったけど、目を通そうともしてくれなくて・・・。", "choices": ["一応、目を通してはくれたんだ", "へぇー、まったく読んでもらえなかったんだ", "そうか、受け入れてくれたんだね"], "ans": 2}, {"stem": "今日の美術展、すごい人だったね。前もってチケット買っておかなかったら、入れなかったよね。", "choices": ["事前に買っておいてよかった", "早めに買っておくべきだったね", "事前に買う必要はなかったね"], "ans": 1}, {"stem": "今の村田監督の映画、僕たちファンの期待を裏切らない出来だったね。", "choices": ["やっぱり村田監督だよね", "え、どこか気に入らないところあったの?", "そんなにがっかりしないでよ"], "ans": 1}, {"stem": "演劇の舞台裏を扱った番組を見たんだけど、製作スタッフあっての舞台なんだと思ったよ", "choices": ["確かに、スタッフよりも俳優次第だよね", "裏で支えた人の力が大切なんだね", "スタッフだけじゃ舞台を作れないもんね"], "ans": 2}, {"stem": "うちの会社、最近経理のソフトウェアを変えたんだけど、使い方がややこしくて先が思いやられるよ。", "choices": ["それは期待できるね", "そのうち慣れるんじゃない?", "え?ソフトウェアは使うのやめちゃったんだ"], "ans": 2}]}, "2024-07": {"examLabel": "2024-07", "audioSrc": "assets/audio/MD4/N1_7-2024.mp3", "questions": [{"stem": "今日の授業のレポート、そう簡単には書けそうもないよね。", "choices": ["大変だけどやるしかないよ。", "難しいと思ってないの?", "本当、簡単で助かるよね。"], "ans": 1}, {"stem": "僕こないだから和田さんと揉めてて・・・。", "choices": ["2人で楽しそうだね。", "仲直りしたんだ。", "何で?何があったの?"], "ans": 3}, {"stem": "さっき見た映画の最後のシーン、私、胸を打たれた。", "choices": ["どうしてワクワクしたの?", "僕もあのシーン意味不明だったよ。", "感動的だったよね。"], "ans": 3}, {"stem": "お昼の定食屋で飲んだサービスのコーヒー、飲めたもんじゃなかったね。", "choices": ["もっと飲めばよかったね。", "確かにあれはおいしかったね。", "ちょっとひどかったよね。"], "ans": 3}, {"stem": "森さんのことだから遅刻するはずないのに来ないね。", "choices": ["いいかげん、ちゃんとしてほしいよね。", "森さんってよく遅刻するんだ。", "遅れるなんてどうしたんだろう?"], "ans": 3}, {"stem": "昨日のサークルの部員同士の言い合い、先輩に報告するまでもないよね。", "choices": ["え?先輩に言うんだね。", "必要ないよね。", "報告した方がいいってことね。"], "ans": 2}, {"stem": "昨日うちの学校の柔道の試合、見に行ったんだけど、負けはしないかハラハラしたよ。", "choices": ["何とか勝てたんだ。", "負けちゃって残念だったね。", "余裕で勝ったんだね。"], "ans": 1}, {"stem": "課長、桜社への商品説明、私の担当なんですが、ご一緒願えないでしょうか", "choices": ["かまいませんよ、行きますよ。", "担当者が行かないのはまずいでしょう。", "私が代わりに行くんですね。"], "ans": 1}, {"stem": "加藤さん、データの分析は木村さんにかなう人はいないよね。", "choices": ["え?木村さんさっぱり分かってないの？", "木村さんが1番詳しいと思う。", "木村さん、データの分析は苦手らしいね。"], "ans": 2}, {"stem": "課長に急にイベントの手伝い頼まれたけど、断るに断れなかったよ。", "choices": ["頼まれたら断れないよね。", "頼まれたのに断ったんだ。", "本当は断りたくなかったんだね。"], "ans": 1}, {"stem": "新人の渡辺さん、先月の営業成績、ベテランの課長に迫る勢いだったって。", "choices": ["課長の成績には全然届かないんだね。", "あと少しで課長を抜くぐらいだったんだ。", "課長を超える結果だなんてすごいね。"], "ans": 2}]}, "2024-12": {"examLabel": "2024-12", "audioSrc": "assets/audio/MD4/N1_12-2024.mp3", "questions": [{"stem": "先輩。テニスの全国大会、きっと優勝してみせます。", "choices": ["全力を出してくるよ。", "諦めるのは早いんじゃない?", "うん、期待してるからね。"], "ans": 3}, {"stem": "ねぇ、歌手の森なお、明日のコンサートを最後に引退だって。知ってた?", "choices": ["え?明日で引退するの?どうして?", "え?コンサートだけは続けるんだ。", "え?明日のコンサート中止になったの?"], "ans": 1}, {"stem": "ゼミでやった実験、データを整理するのに手こずったね。", "choices": ["確かにスムーズにいったよね。", "あぁ、もっと大変だと思っていたんだね。", "本当、途中で嫌になっちゃったよ。"], "ans": 3}, {"stem": "美容師さんに言われるままにパーマかけちゃったけど、どうかな?", "choices": ["え?美容師さんにアドバイスもらわなかったんだ。", "美容師さんの言うとおりにして正解だよ。", "美容師さんの勧めるスタイルにすればよかったかもね。"], "ans": 2}, {"stem": "研究会の発表の事前練習、明日なら見てあげられなくもないよ。", "choices": ["どうしても明日は難しいですか?", "すみません。では、明日お願いします。", "じゃ、今日のほうがいいんですね。"], "ans": 2}, {"stem": "ねぇ、私たち午後から出張だけど、新幹線、今運転を見合わせてるって。", "choices": ["え?いつ頃運転を再開するんだろう。", "あ、新幹線動いたんだ。よかった。", "じゃ、予定を変更しなくてよさそうだね。"], "ans": 1}, {"stem": "あの、このカウンターで3000円以上のレシートと引き換えにお皿もらえるって聞いたんですが・・・。", "choices": ["あ、商品のお取替えをご希望ですね。", "3000円のご予算でお求めでしょうか。", "あ、はい。レシートをお預かりします。"], "ans": 3}, {"stem": "ゼミの食事会、いつもの店に電話したんだけど、キャンセルが出ない限り、席確保できないって", "choices": ["あー、キャンセルできないんだね。", "じゃ、何とか予約取れそうだね。", "じゃ、他の店探すしかないね。"], "ans": 3}, {"stem": "山本課長って先月この支店に異動してきたと思ったら、海外に転勤だって。", "choices": ["こないだ来たばっかりなのにまた異動?", "え?この支店に来るはずが海外転勤になったの?", "課長、長いことこの支店にいたもんね。"], "ans": 1}, {"stem": "卒業論文の提出まであと10 日で切羽詰まってきたよ。", "choices": ["へぇー、余裕があるんだね。", "あと少しだから頑張って。", "すごい、もう書き終わったんだね。"], "ans": 2}, {"stem": "みどり社との共同研究、中止を余儀なくされたって課長が言ってたよ。", "choices": ["今になって中止にはできないもんね。", "え?いったい何があったの?", "あぁ、続けられることになったんだね。"], "ans": 2}]}, "2025-07": {"examLabel": "2025-07", "audioSrc": "assets/audio/MD4/N1_7-2025.mp3", "questions": [{"stem": "営業部の伊藤さんと原田さん、この頃ギクシャクしてない。", "choices": ["コミュニケーションがうまく取れてるんですね", "人気が合ってていいね", "会議で言い合いになってたってよ"], "ans": 3}, {"stem": "日曜日に引っ越すんだって?土曜日なら手伝えたんだけど。", "choices": ["人は足りてるから大丈夫だよ", "じゃ、日曜日待ってるね", "日曜日に手伝ってくれるの？"], "ans": 1}, {"stem": "小野さん、会議で出すペットボトルのお茶、切らしてますよ。", "choices": ["お茶足りて良かったですね", "古いものは捨てておきます", "あ、全然ありませんか？すぐ注文します"], "ans": 3}, {"stem": "今年から営業部に移動したんですけど、一向に慣れないんですよ。", "choices": ["そのうち慣れますよ", "慣れるの早いですね", "少し慣れてきたんですね"], "ans": 1}, {"stem": "さっき先輩が体育館に入ってくるなり出てっちゃったよ。", "choices": ["すぐに？どうしたんだろうね", "しばらくは体育館にいたんだね", "体育館に入って来なかったの？"], "ans": 1}, {"stem": "工事の報告ですが、スケジュールになんら天候不良の影響はありません。", "choices": ["困りましたね。すぐに対策を考えないとね", "全く問題ないんですね。それは安心しました", "スケジュールにちょっと遅れが出ているんですね"], "ans": 1}, {"stem": "安倍さん。先月のプロジェクト、山田さんがいなければ失敗してたと思いませんか?", "choices": ["残念だけど、仕方ないですね", "山田さんがいてくれたらよかったですね", "本当、山田さんのおかげですね"], "ans": 3}, {"stem": "ねー、森さん。本田さんがまくらを変えたら、いびきを一切かかなくなったんだって。", "choices": ["やっぱりまくらを変えたくらいじゃ変わらないんだ", "いびきが小さくなったの？", "まくらでそんなに違うんだ"], "ans": 3}, {"stem": "免許や資格は仕事で使えてこそだと思わない?", "choices": ["仕事で役に立つものがいいね", "資格なら何でもいいって話？", "仕事で使えなくてもいいんだ"], "ans": 1}, {"stem": "青葉食品って昔ながらの方法で味噌を作ってるんだって。", "choices": ["昔とは違う方法で作ってるんだね", "へー、昔からずっと変わらないんだ", "最新の技術を導入してるなんてすごいね"], "ans": 2}, {"stem": "うちの課に新しく入った野田さんを見てると、手伝わずにはいられないんですよ。", "choices": ["何もサポートの必要がないんですね", "つい手伝いたくなっちゃいますよね", "もう1人でできるようになったんですね"], "ans": 2}]}, "2025-12": {"examLabel": "2025-12", "audioSrc": "assets/audio/MD4/N1_12-2025.mp3", "questions": [{"stem": "小野くん。昨日、小野くんが出たサッカー部の試合観たけど、チームがまとまってたね。", "choices": ["うーん、何が問題なんだろうね。", "ありがとう。お互いのプレイを信頼しているからね。", "チームがバラバラなの、観ててもわかるんだね。"], "ans": 2}, {"stem": "課長、来月からカメラの部品の値上げをすること、あおば社にお話し願えますか。", "choices": ["ありがとう。説明してくれるんですね。", "わかりました。任せておいてください。", "じゃ、あおば社に価格を聞いておいてください。"], "ans": 2}, {"stem": "来週のグループ発表の準備、ぐずぐずしてはいられないね。", "choices": ["急いでまとめないとね。", "じゃ、ゆっくり進めようか。", "え、準備、一緒にできないの？"], "ans": 1}, {"stem": "さっき見た映画の主役、あの迫力ある演技は彼ならではだよね。", "choices": ["彼にはできない演技だよね。", "彼の演技に不満なの？", "あれは彼にしかできないよね。"], "ans": 3}, {"stem": "昼に駅前の店で食べてきたけど、「昼の営業は本日をもって終了」って書いてあったよ。", "choices": ["本当？明日から昼はやらないのか。", "え、今日は早めに終わっちゃうの？", "あー、今日は昼だけの営業なんだ。"], "ans": 1}, {"stem": "佐藤くんの誕生日会、本人に内緒のはずが、バレてたよ。", "choices": ["いつわかっちゃうか、ハラハラするね。", "まだ佐藤君は気づいてないんだね。", "えー、どうしてわかっちゃったの？"], "ans": 3}, {"stem": "うちの1年生、次の大会で期待できそうなのは林さんぐらいだよね。", "choices": ["他の1年生のレベル上げなきゃね。", "今年の1年生、みんなレベル高いからね。", "じゃ、どの人ならいいと思う？"], "ans": 1}, {"stem": "今の会議、私が最後に質問したばっかりに長引いちゃったね。", "choices": ["気にしないで聞けばよかったのに。", "聞きたいことあったんだから、いいんじゃない？", "他にも質問したいこと、出てきちゃったの？"], "ans": 2}, {"stem": "田中さん、新商品の発表会、「前倒しでやれないか」って、社長が...。", "choices": ["え、予定より遅れるんですか？", "え、発表会の前に何をするんですか？", "え、どのくらい早めたいんでしょうか？"], "ans": 3}, {"stem": "サッカーの森監督、来年はチームの監督を務めると同時に会長にも就くんだってね。", "choices": ["え、監督辞めちゃうの？", "どちらか選ばざるを得ないんだね。", "両方なんて大変そうだね。"], "ans": 3}, {"stem": "さっき言ってた奨学金の申請、先輩に聞いた限りでは学年の条件はないって。", "choices": ["え、これから先輩が調べてくれるの？", "じゃ、僕も申し込めるかも。", "先輩も自信がないんだね。"], "ans": 2}]}};
